package com.thrallinone;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;

/**
 * Raid fights are filed under the raid rather than the NPC: a raid room has
 * many NPCs, and players compare whole raids. Raids are told apart by the map
 * region of the room's template (raids are instanced).
 */
final class BossKey
{
	static final String COX = "Chambers of Xeric";
	static final String TOB = "Theatre of Blood";
	static final String TOA = "Tombs of Amascut";
	static final String TFA = "The Fractured Archive";

	/** Maiden, Bloat, Nylocas, Sotetseg (and its maze), Xarpus, Verzik. */
	private static final Set<Integer> TOB_REGIONS = ImmutableSet.of(12613, 13125, 13122, 13123, 13379, 12612, 12611);
	/** Nexus, the four paths (puzzle room and boss each), the Wardens and the tomb. */
	private static final Set<Integer> TOA_REGIONS = ImmutableSet.of(
		14160,
		14674, 14676,
		15698, 15700,
		14162, 14164,
		15186, 15188,
		15184, 15696,
		14672);
	/** The nexus (with the Archive Guardian), Ocellus, Ezekiel, the Dagon'hai, Moia, Xarth, Bork and Dreadnoth. */
	private static final Set<Integer> TFA_REGIONS = ImmutableSet.of(
		16471, 16472,
		16214, 16215, 16216,
		16726, 16727, 16728);

	private static final Set<String> RAIDS = ImmutableSet.of(COX, TOB, TOA, TFA);

	private BossKey()
	{
	}

	/** Whether a saved boss key is one of the raids (shown in its own section). */
	static boolean isRaid(String boss)
	{
		return RAIDS.contains(boss);
	}

	/** The raid we are standing in, or null. Client thread. */
	@Nullable
	static String current(Client client)
	{
		boolean inChambers = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
		return raid(inChambers, templateRegion(client));
	}

	/** The region we stand in, as the map has it outside instances; -1 if unknown. Client thread. */
	static int templateRegion(Client client)
	{
		Player me = client.getLocalPlayer();
		WorldPoint location = me == null ? null : WorldPoint.fromLocalInstance(client, me.getLocalLocation());
		return location == null ? -1 : location.getRegionID();
	}

	/** The raid we are in, from the Chambers of Xeric varbit and the template region, or null. */
	@Nullable
	static String raid(boolean inChambers, int templateRegion)
	{
		if (inChambers)
		{
			return COX;
		}
		if (TOB_REGIONS.contains(templateRegion))
		{
			return TOB;
		}
		if (TOA_REGIONS.contains(templateRegion))
		{
			return TOA;
		}
		if (TFA_REGIONS.contains(templateRegion))
		{
			return TFA;
		}
		return null;
	}
}

package com.thrallinone;

import java.util.Collection;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/**
 * How many Resurrect spells of a tier the runes you carry pay for. Pure, so
 * it can be unit-tested; {@link ThrallCasts} gathers the items from the client.
 *
 * <p>A combination rune counts towards each of its two runes. That is exact
 * here because no rune item counts as two of the runes one thrall spell needs
 * (each tier needs a single elemental rune, and the aether rune's soul half
 * is never needed).
 */
public final class CastsCounter
{
	private CastsCounter()
	{
	}

	/**
	 * @param carried item ID to quantity, from the inventory and, if a rune pouch is in the inventory, its contents
	 * @param worn the item IDs of worn equipment, for staves and tomes that supply runes
	 * @return the number of casts the runes pay for
	 */
	public static int castsLeft(ThrallTier tier, Map<Integer, Integer> carried, Collection<Integer> worn)
	{
		Set<Rune> free = EnumSet.noneOf(Rune.class);
		for (int itemId : worn)
		{
			Set<Rune> runes = Rune.INFINITE.get(itemId);
			if (runes != null)
			{
				free.addAll(runes);
			}
		}

		Map<Rune, Long> have = new EnumMap<>(Rune.class);
		for (Map.Entry<Integer, Integer> item : carried.entrySet())
		{
			Set<Rune> runes = Rune.ITEMS.get(item.getKey());
			if (runes != null && item.getValue() > 0)
			{
				for (Rune rune : runes)
				{
					have.merge(rune, (long) item.getValue(), Long::sum);
				}
			}
		}

		long casts = Integer.MAX_VALUE;
		for (Map.Entry<Rune, Integer> cost : tier.getRunes().entrySet())
		{
			if (!free.contains(cost.getKey()))
			{
				casts = Math.min(casts, have.getOrDefault(cost.getKey(), 0L) / cost.getValue());
			}
		}
		return (int) casts;
	}
}

package com.thrallinone;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** Which thralls' outlines take their color from the thrall's type (Mage, Ranged, Melee). */
@Getter
@RequiredArgsConstructor
public enum ColorByType
{
	OFF("Off", false, false),
	YOURS("Yours", true, false),
	OTHERS("Others", false, true),
	BOTH("Both", true, true);

	private final String name;
	/** Your thrall uses Your Type Colors. */
	private final boolean yours;
	/** Other players' thralls use Others' Type Colors. */
	private final boolean others;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.thrallinone;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.Setter;

/**
 * One fight while it is going on: how long it lasted, how much of that our
 * thrall was out, and the damage dealt by us and by our thrall.
 *
 * <p>A fight runs from our first hit (ours or our thrall's) to our last one,
 * so the wait after the last hit before the fight is called over doesn't
 * count against uptime. Ticks after the latest hit are held back and only
 * counted once another hit shows the fight carried on.
 */
class Fight
{
	static final double SECONDS_PER_TICK = 0.6;

	@Getter
	private int lastHitTick;

	@Getter
	private int ticks;
	@Getter
	private int thrallTicks;
	private final int[] tierTicks = new int[ThrallTier.values().length];
	private int pendingTicks;
	private int pendingThrallTicks;
	private final int[] pendingTierTicks = new int[ThrallTier.values().length];

	/** All our hitsplats on NPCs, the thrall's included (the game shows them as ours). */
	@Getter
	private int totalDamage;
	@Getter
	private int thrallDamage;
	private final Map<ThrallType, Integer> damageByType = new EnumMap<>(ThrallType.class);

	/** Damage (ours and our thrall's) by target, to find who the fight was against. */
	private final Map<Object, Integer> damageByTarget = new HashMap<>();
	private final Map<Object, String> targetNames = new HashMap<>();

	/** The raid this fight is in, if any: raid fights are grouped by raid. */
	@Getter
	@Setter
	@Nullable
	private String raid;

	Fight(int startTick)
	{
		this.lastHitTick = startTick;
	}

	/** Count one game tick, noting whether our thrall was out and its tier (null if unknown). */
	void tick(int tick, boolean thrallOut, @Nullable ThrallTier tier)
	{
		if (tick <= lastHitTick)
		{
			countTick(thrallOut, tier);
		}
		else
		{
			pendingTicks++;
			if (thrallOut)
			{
				pendingThrallTicks++;
				if (tier != null)
				{
					pendingTierTicks[tier.ordinal()]++;
				}
			}
		}
	}

	private void countTick(boolean thrallOut, @Nullable ThrallTier tier)
	{
		ticks++;
		if (thrallOut)
		{
			thrallTicks++;
			if (tier != null)
			{
				tierTicks[tier.ordinal()]++;
			}
		}
	}

	/** One of our hitsplats (ours or our thrall's) on an NPC. */
	void hit(int tick, Object target, String targetName, int amount)
	{
		totalDamage += amount;
		damageByTarget.merge(target, amount, Integer::sum);
		targetNames.put(target, targetName);
		extendTo(tick);
	}

	/** A hitsplat already passed to {@link #hit} that turned out to be our thrall's. */
	void thrallHit(int tick, @Nullable ThrallType type, int amount)
	{
		thrallDamage += amount;
		if (type != null)
		{
			damageByType.merge(type, amount, Integer::sum);
		}
		extendTo(tick);
	}

	private void extendTo(int tick)
	{
		if (tick <= lastHitTick)
		{
			return;
		}
		lastHitTick = tick;
		ticks += pendingTicks;
		thrallTicks += pendingThrallTicks;
		for (int i = 0; i < tierTicks.length; i++)
		{
			tierTicks[i] += pendingTierTicks[i];
			pendingTierTicks[i] = 0;
		}
		pendingTicks = 0;
		pendingThrallTicks = 0;
	}

	/** Game ticks in this many seconds, rounding up. */
	static int secondsToTicks(int seconds)
	{
		return (seconds * 10 + 5) / 6;
	}

	/** Our own damage, without the thrall's. */
	int getOwnDamage()
	{
		return Math.max(0, totalDamage - thrallDamage);
	}

	/** The target that took the most damage, or null before the first hit. */
	@Nullable
	Object getMainTarget()
	{
		Object best = null;
		int bestDamage = -1;
		for (Map.Entry<Object, Integer> entry : damageByTarget.entrySet())
		{
			if (entry.getValue() > bestDamage)
			{
				best = entry.getKey();
				bestDamage = entry.getValue();
			}
		}
		return best;
	}

	String getMainTargetName()
	{
		Object main = getMainTarget();
		return main == null ? "Unknown" : targetNames.get(main);
	}

	/** Where the fight is filed: the raid it was in, or the name of the NPC it was mostly against. */
	String getBoss()
	{
		return raid != null ? raid : getMainTargetName();
	}

	/** Expected DPS for the tiers our thrall had out this fight, weighted by time; 0 if none known. */
	double getExpectedDps()
	{
		int known = 0;
		double sum = 0;
		for (ThrallTier tier : ThrallTier.values())
		{
			known += tierTicks[tier.ordinal()];
			sum += tierTicks[tier.ordinal()] * tier.getExpectedDps();
		}
		return known == 0 ? 0 : sum / known;
	}

	FightRecord toRecord()
	{
		FightRecord record = new FightRecord();
		record.setBoss(getBoss());
		record.setTicks(Math.max(1, ticks));
		record.setThrallTicks(Math.min(thrallTicks, Math.max(1, ticks)));
		record.setThrallDamage(thrallDamage);
		record.setOwnDamage(getOwnDamage());
		record.setExpectedDps(getExpectedDps());
		record.setDamageByType(new EnumMap<>(damageByType));
		return record;
	}
}

package com.thrallinone;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Data;

/** A finished fight: the facts the session and the saved totals are added up from. Not saved itself. */
@Data
class FightRecord
{
	/** Where the fight is filed: the NPC it was mostly against, or the raid. */
	private String boss;
	private int ticks;
	/** Ticks of the fight with our thrall out. */
	private int thrallTicks;
	private int thrallDamage;
	/** Our own damage, without the thrall's. */
	private int ownDamage;
	/** The wiki's DPS for the thrall tiers we had out, weighted by time. */
	private double expectedDps;
	private Map<ThrallType, Integer> damageByType = new LinkedHashMap<>();
}

package com.thrallinone;

import lombok.Data;
import lombok.NoArgsConstructor;

/** Fights added up: for the login session, one boss, or a lifetime. */
@Data
@NoArgsConstructor
class FightTotals
{
	private int fights;
	private long ticks;
	private long thrallTicks;
	private long thrallDamage;
	private long ownDamage;
	/** Sum over fights of the expected DPS times the thrall's time out, for an overall expected DPS. */
	private double expectedDamage;

	FightTotals(FightTotals other)
	{
		fights = other.fights;
		ticks = other.ticks;
		thrallTicks = other.thrallTicks;
		thrallDamage = other.thrallDamage;
		ownDamage = other.ownDamage;
		expectedDamage = other.expectedDamage;
	}

	void add(FightRecord fight)
	{
		fights++;
		ticks += fight.getTicks();
		thrallTicks += fight.getThrallTicks();
		thrallDamage += fight.getThrallDamage();
		ownDamage += fight.getOwnDamage();
		expectedDamage += fight.getExpectedDps() * fight.getThrallTicks() * Fight.SECONDS_PER_TICK;
	}

	double uptime()
	{
		return ticks <= 0 ? 0 : (double) thrallTicks / ticks;
	}

	double share()
	{
		long total = ownDamage + thrallDamage;
		return total <= 0 ? 0 : (double) thrallDamage / total;
	}

	double measuredDps()
	{
		return thrallTicks <= 0 ? 0 : thrallDamage / (thrallTicks * Fight.SECONDS_PER_TICK);
	}

	double expectedDps()
	{
		return thrallTicks <= 0 ? 0 : expectedDamage / (thrallTicks * Fight.SECONDS_PER_TICK);
	}
}

