package com.thrallinone;

import java.util.Arrays;

/**
 * A class which manages 1024-sized blocks of memory.
 *
 * <p>Copied unchanged from RuneLite's net.runelite.client.ui.overlay.outline
 * package, where it is package-private, for {@link ThrallOutlineRenderer}.
 */
class IntBlockBuffer
{
	public static final int BLOCK_BITS = 10;
	public static final int BLOCK_SIZE = 1 << BLOCK_BITS;

	private int[] memory = new int[0];
	private int[] unusedBlockIndices = new int[0];
	private int unusedBlockIndicesLength;

	private void increaseBlockCount()
	{
		int currBlockCount = memory.length >> BLOCK_BITS;
		int newBlockCount = Math.max(1, currBlockCount * 2);
		memory = Arrays.copyOf(memory, newBlockCount * BLOCK_SIZE);
		unusedBlockIndices = Arrays.copyOf(unusedBlockIndices, newBlockCount);
		for (int i = currBlockCount; i < newBlockCount; i++)
		{
			unusedBlockIndices[unusedBlockIndicesLength++] = i;
		}
	}

	/**
	 * Retrieves the whole memory buffer.
	 */
	public int[] getMemory()
	{
		return memory;
	}

	/**
	 * Marks a new block as used.
	 *
	 * @return The index of the block.
	 */
	public int useNewBlock()
	{
		if (unusedBlockIndicesLength == 0)
		{
			increaseBlockCount();
		}

		return unusedBlockIndices[--unusedBlockIndicesLength];
	}

	/**
	 * Marks a block as unused.
	 *
	 * @param index The index of the block. The block should be in use before calling this method.
	 */
	public void freeBlock(int index)
	{
		unusedBlockIndices[unusedBlockIndicesLength++] = index;
	}
}

package com.thrallinone;

import lombok.RequiredArgsConstructor;

/** Which thralls' sounds are silenced. */
@RequiredArgsConstructor
public enum MuteThralls
{
	OFF("Off"),
	OTHERS("Other Thralls"),
	ALL("All Thralls");

	private final String name;

	/** Whether a sound made by a thrall is silenced, given whether that thrall is ours. */
	boolean mutes(boolean owned)
	{
		return this == ALL || (this == OTHERS && !owned);
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.thrallinone;

import com.google.common.collect.ImmutableSet;
import java.util.Collection;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.api.gameval.NpcID;

/**
 * Places where you can fight but can't summon a thrall, so reminders there
 * would only nag. The OSRS wiki ("Thrall", where thralls cannot be
 * resurrected) lists them; the ones matched exactly are below. Everywhere else
 * the plugin learns a spot from the game's own chat line when a cast fails.
 *
 * <p>Region ids are template regions (WorldPoint.fromLocalInstance), so they
 * hold inside instances. Sailing is matched by the player standing on a boat's
 * WorldView instead of a region.
 */
final class NoSummonAreas
{
	/** Nightmare Zone dreams. RuneLite core's Nightmare Zone and Discord plugins use the same region. */
	static final int NIGHTMARE_ZONE_REGION = 9033;
	/**
	 * Temple of the Eye (Guardians of the Rift). The wiki places it at 3613, 9501,
	 * which is region 14484; RuneLite core's Discord plugin uses the same id.
	 */
	static final int GUARDIANS_OF_THE_RIFT_REGION = 14484;
	/** Player-owned house instance templates, as listed in RuneLite core's Discord plugin. */
	static final Set<Integer> POH_REGIONS = ImmutableSet.of(7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);

	private static final Set<Integer> FIXED_REGIONS = ImmutableSet.<Integer>builder()
		.add(NIGHTMARE_ZONE_REGION)
		.add(GUARDIANS_OF_THE_RIFT_REGION)
		.addAll(POH_REGIONS)
		.build();

	/**
	 * Quest bosses fought in instances where thralls can't be summoned. Matched by
	 * NPC so we don't need each instance's region. Fight forms only, plus the
	 * forms each boss switches to mid-fight.
	 */
	private static final Set<Integer> QUEST_BOSSES = ImmutableSet.of(
		// Galvek (Dragon Slayer II)
		NpcID.GALVEK_WAVES, NpcID.GALVEK_FIRE, NpcID.GALVEK_WATER, NpcID.GALVEK_WIND,
		NpcID.GALVEK_EARTH, NpcID.GALVEK_TSUNAMI,
		// Robert the Strong (Dragon Slayer II)
		NpcID.DREAM_ROBERT_COMBAT,
		// Vanstrom Klause (Sins of the Father)
		NpcID.MYQ5_VANSTROM_COMBAT, NpcID.MYQ5_VANSTROM_COMBAT_NOOP, NpcID.MYQ5_VANSTROM_COMBAT_ENRAGE,
		// Fragment of Seren (Song of the Elves)
		NpcID.DARK_SEREN, NpcID.DARK_SEREN_PHANTOM,
		// Lowerniel Drakan (The Blood Moon Rises)
		NpcID.MYQ6_LOWERNIEL_FINAL_COMBAT
	);

	/**
	 * The game's line when a thrall can't be resurrected where you stand. It has
	 * more than one wording, such as "You can't resurrect a thrall here." (Chasm
	 * of Fire) and "The ground is too soft to resurrect a thrall here."
	 * (Jormungand's Prison). Both say "resurrect", "thrall" and "here", so match
	 * on those.
	 */
	static final Pattern CANT_SUMMON_MESSAGE = Pattern.compile("\\bresurrect\\b.*\\bthralls?\\b.*\\bhere\\b",
		Pattern.CASE_INSENSITIVE);

	/** Game messages about thralls, for debug logging. */
	private static final Pattern THRALL_MESSAGE = Pattern.compile("thrall|resurrect", Pattern.CASE_INSENSITIVE);

	private NoSummonAreas()
	{
	}

	static boolean isFixedRegion(int regionId)
	{
		return FIXED_REGIONS.contains(regionId);
	}

	static boolean isQuestBoss(int npcId)
	{
		return QUEST_BOSSES.contains(npcId);
	}

	static boolean isCantSummonMessage(String message)
	{
		return message != null && CANT_SUMMON_MESSAGE.matcher(message).find();
	}

	static boolean mentionsThralls(String message)
	{
		return message != null && THRALL_MESSAGE.matcher(message).find();
	}

	/** Learned regions as saved in the profile: comma-separated ids. Anything unreadable is skipped. */
	static Set<Integer> parseRegions(String saved)
	{
		Set<Integer> regions = new TreeSet<>();
		if (saved == null)
		{
			return regions;
		}
		for (String part : saved.split(","))
		{
			try
			{
				regions.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException e)
			{
				// Skip it.
			}
		}
		return regions;
	}

	static String formatRegions(Collection<Integer> regions)
	{
		return regions.stream().sorted().map(String::valueOf).collect(Collectors.joining(","));
	}
}

package com.thrallinone;

import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

/**
 * Whether we stand somewhere a thrall can't be summoned: a place from
 * {@link NoSummonAreas}, on a boat, in a quest boss fight, or a region where
 * the game told us so. Learned regions are saved per account in the RuneLite
 * profile, and dropped again if a thrall is summoned there after all.
 */
@Slf4j
@Singleton
public class NoSummonTracker
{
	private static final String LEARNED_KEY = "noSummonRegions";

	private final Client client;
	private final ConfigManager configManager;

	private final Set<Integer> learned = new HashSet<>();
	private final Set<NPC> questBosses = new HashSet<>();
	private int regionId = -1;
	private boolean onBoat;
	private boolean noSummonHere;

	@Inject
	NoSummonTracker(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	void reset()
	{
		loadLearned();
		questBosses.clear();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			for (NPC npc : client.getTopLevelWorldView().npcs())
			{
				if (NoSummonAreas.isQuestBoss(npc.getId()))
				{
					questBosses.add(npc);
				}
			}
		}
		update();
	}

	/** Updated once a tick, before the reminders read it. */
	public boolean isNoSummonHere()
	{
		return noSummonHere;
	}

	@Subscribe(priority = 1)
	public void onGameTick(GameTick event)
	{
		update();
	}

	private void update()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			regionId = -1;
			onBoat = false;
			noSummonHere = false;
			return;
		}

		WorldView view = me.getWorldView();
		boolean nowOnBoat = view != null && !view.isTopLevel();
		LocalPoint local = me.getLocalLocation();
		WorldPoint where = local == null ? null : WorldPoint.fromLocalInstance(client, local);
		int nowRegion = where == null ? -1 : where.getRegionID();

		boolean now = nowOnBoat
			|| !questBosses.isEmpty()
			|| NoSummonAreas.isFixedRegion(nowRegion)
			|| learned.contains(nowRegion);
		if (now != noSummonHere || nowOnBoat != onBoat)
		{
			log.debug("Can't summon here: {} (region {}, on a boat {}, quest bosses {}, learned {})",
				now, nowRegion, nowOnBoat, questBosses.size(), learned.contains(nowRegion));
		}
		regionId = nowRegion;
		onBoat = nowOnBoat;
		noSummonHere = now;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM && type != ChatMessageType.ENGINE)
		{
			return;
		}
		String message = event.getMessage();
		if (!NoSummonAreas.mentionsThralls(message))
		{
			return;
		}
		log.debug("Thrall game message ({}) in region {}: {}", type, regionId, message);

		if (NoSummonAreas.isCantSummonMessage(message) && regionId >= 0 && !onBoat
			&& !NoSummonAreas.isFixedRegion(regionId) && learned.add(regionId))
		{
			log.debug("Learned no-summon region {}", regionId);
			saveLearned();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// A thrall came out here, so this isn't a no-summon spot after all.
		if (event.getVarbitId() == VarbitID.ARCEUUS_RESURRECTION_ACTIVE && event.getValue() != 0
			&& regionId >= 0 && learned.remove(regionId))
		{
			log.debug("Summoned in learned no-summon region {}; forgetting it", regionId);
			saveLearned();
			update();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (NoSummonAreas.isQuestBoss(npc.getId()))
		{
			questBosses.add(npc);
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		if (NoSummonAreas.isQuestBoss(npc.getId()))
		{
			questBosses.add(npc);
		}
		else
		{
			questBosses.remove(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		questBosses.remove(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			questBosses.clear();
			update();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadLearned();
	}

	private void loadLearned()
	{
		learned.clear();
		learned.addAll(NoSummonAreas.parseRegions(
			configManager.getRSProfileConfiguration(ThrallInOneConfig.GROUP, LEARNED_KEY)));
		if (!learned.isEmpty())
		{
			log.debug("Loaded learned no-summon regions {}", learned);
		}
	}

	private void saveLearned()
	{
		if (learned.isEmpty())
		{
			configManager.unsetRSProfileConfiguration(ThrallInOneConfig.GROUP, LEARNED_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(ThrallInOneConfig.GROUP, LEARNED_KEY,
				NoSummonAreas.formatRegions(learned));
		}
	}
}

