/**
 * Thrall casts left from the runes in the inventory and rune pouch, with
 * worn staves and tomes supplying their runes. The tier counted is the one
 * we last cast (taken from our claimed thrall's NPC ID and saved to the
 * RuneLite profile), or greater before the first cast. Counted
 * on the game tick after the inventory, equipment, rune pouch or setting
 * changes, and sent to the sidebar panel. Below the "Low below" mark it can
 * notify once.
 */
@Slf4j
@Singleton
public class ThrallCasts
{
	private static final String LAST_TIER_KEY = "lastThrallTier";

	private final Client client;
	private final ThrallTracker tracker;
	private final ThrallReminders reminders;
	private final ThrallInOneConfig config;
	private final ConfigManager configManager;
	private final Notifier notifier;

	private int castsLeft = -1;
	/** The low-casts notification has fired for this drop below the low mark. */
	private boolean lowNotified;
	/** Where the count goes; null while the sidebar panel is off. */
	@Nullable
	private volatile ThrallPanel panel;
	/** We carry the Book of the Dead and are on the Arceuus spellbook: the count is worth showing. */
	private boolean canSummon;
	@Nullable
	private ThrallTier lastTier;
	private boolean lastTierLoaded;
	@Nullable
	private NPC seenOwned;
	private boolean dirty;
	/** What the panel was last sent, so a recount that changes nothing isn't sent again. */
	@Nullable
	private String pushed;

	@Inject
	ThrallCasts(Client client, ThrallTracker tracker, ThrallReminders reminders, ThrallInOneConfig config,
		ConfigManager configManager, Notifier notifier)
	{
		this.client = client;
		this.tracker = tracker;
		this.reminders = reminders;
		this.config = config;
		this.configManager = configManager;
		this.notifier = notifier;
	}

	void reset()
	{
		castsLeft = -1;
		canSummon = false;
		lastTier = null;
		lastTierLoaded = false;
		seenOwned = null;
		dirty = true;
		pushed = null;
		pushToPanel();
	}

	/** The tier counted: the last one we cast, or greater before our first cast. */
	public ThrallTier getNextTier()
	{
		return lastTier != null ? lastTier : ThrallTier.GREATER;
	}

	public boolean isLow()
	{
		return castsLeft >= 0 && castsLeft < config.castsWarnBelow();
	}

	void setPanel(@Nullable ThrallPanel panel)
	{
		this.panel = panel;
	}

	/** Push the count to a freshly shown panel. Client thread. */
	void refreshPanel()
	{
		pushed = null;
		pushToPanel();
	}

	/**
	 * Send the count to the panel if it changed since the last push. The
	 * inventory changes with nearly every attack or spell, and rebuilding the
	 * box each time would drop its tooltip mid-fight.
	 */
	private void pushToPanel()
	{
		ThrallPanel target = panel;
		if (target == null)
		{
			return;
		}
		boolean enabled = config.castsEnabled();
		int left = castsLeft;
		ThrallTier tier = getNextTier();
		boolean low = isLow();
		boolean summon = canSummon;
		String shown = enabled + "/" + left + "/" + tier + "/" + low + "/" + summon;
		if (shown.equals(pushed))
		{
			return;
		}
		pushed = shown;
		SwingUtilities.invokeLater(() -> target.showCasts(enabled, left, tier, low, summon));
	}

	/**
	 * The low-casts notification, once per drop below the low mark: while we
	 * could summon, and our thrall is out or we're fighting, so it doesn't
	 * fire at the bank. Counting again above the mark re-arms it.
	 */
	private void checkLow()
	{
		if (castsLeft >= 0 && !isLow())
		{
			lowNotified = false;
		}
		else if (!lowNotified && canSummon && isLow() && (tracker.hasActiveThrall() || reminders.isInCombat()))
		{
			lowNotified = true;
			// Counts as sent while off, so turning Casts Left back on doesn't fire for an old drop.
			if (!config.castsEnabled())
			{
				return;
			}
			notifier.notify(config.lowCastsNotification(), castsLeft == 0
				? "No thrall casts left"
				: "Low on thrall casts: " + castsLeft + " left");
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int id = event.getVarbitId();
		if (id == VarbitID.SPELLBOOK || RunePouch.isPouchVarbit(id))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ThrallInOneConfig.GROUP.equals(event.getGroup())
			&& ("castsWarnBelow".equals(event.getKey()) || "castsEnabled".equals(event.getKey())))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!lastTierLoaded)
		{
			// The RuneLite profile is the logged-in account's by the first tick.
			lastTierLoaded = true;
			lastTier = loadLastTier();
			dirty = true;
		}

		NPC owned = tracker.getOwned();
		if (owned != seenOwned)
		{
			seenOwned = owned;
			ThrallTier tier = owned == null ? null : ThrallTier.of(owned.getId());
			if (tier != null && tier != lastTier)
			{
				lastTier = tier;
				configManager.setRSProfileConfiguration(ThrallInOneConfig.GROUP, LAST_TIER_KEY, tier.name());
				log.debug("Last thrall tier now {}", tier);
				dirty = true;
			}
		}

		if (dirty)
		{
			dirty = false;
			count();
			pushToPanel();
		}
		checkLow();
	}

	private void count()
	{
		Map<Integer, Integer> carried = new HashMap<>();
		boolean pouch = false;
		boolean book = false;

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				int id = item.getId();
				if (id > 0)
				{
					carried.merge(id, item.getQuantity(), Integer::sum);
					pouch |= RunePouch.ITEMS.contains(id);
					book |= id == ItemID.BOOK_OF_THE_DEAD;
				}
			}
		}

		List<Integer> worn = new ArrayList<>();
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment != null)
		{
			for (Item item : equipment.getItems())
			{
				if (item.getId() > 0)
				{
					worn.add(item.getId());
					book |= item.getId() == ItemID.BOOK_OF_THE_DEAD;
				}
			}
		}

		// The pouch keeps its contents in varbits, which stay set while the
		// pouch is in the bank, so they only count with a pouch on us.
		if (pouch)
		{
			RunePouch.addContents(client, carried);
		}

		canSummon = book && client.getVarbitValue(VarbitID.SPELLBOOK) == ThrallReminders.ARCEUUS_SPELLBOOK;
		castsLeft = CastsCounter.castsLeft(getNextTier(), carried, worn);
	}

	@Nullable
	private ThrallTier loadLastTier()
	{
		String saved = configManager.getRSProfileConfiguration(ThrallInOneConfig.GROUP, LAST_TIER_KEY);
		if (saved == null)
		{
			return null;
		}
		try
		{
			return ThrallTier.valueOf(saved);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.thrallinone;

import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Pure decision rules for "which of these thralls is mine". Kept free of the
 * client API so the rules can be unit tested; {@link ThrallTracker} gathers
 * the facts about each thrall in the scene and asks this class to choose.
 *
 * <p>Thralls have no owner field, so ownership is inferred from three signals,
 * strongest first:
 * <ol>
 * <li>the thrall is interacting with (following or facing) the local player,
 * and a thrall interacting with some other player is never ours;</li>
 * <li>timing: it appeared close to us within a few ticks of our resurrection
 * varbit turning on;</li>
 * <li>position: while our varbit is on and we have no thrall yet, one that is
 * near us and nearer to us than to any other player.</li>
 * </ol>
 * In game an idle thrall's interacting target is null and a fighting one's is
 * the NPC it attacks, so the first signal rarely fires: timing and position
 * do most of the work (with our cast graphic, see {@link ThrallTracker}).
 */
final class ThrallClaim
{
	/**
	 * The thrall NPC appears before the varbit turns on: measured in game it
	 * spawned 5 ticks earlier (the varbit is set once it has risen).
	 */
	static final int EXPECTED_SPAWN_OFFSET = -5;
	/** A spawn this many ticks before our varbit turned on can still be our cast. */
	static final int CAST_WINDOW_BEFORE_TICKS = 8;
	/** Allowance for the spawn arriving after the varbit instead. */
	static final int CAST_WINDOW_AFTER_TICKS = 3;
	/** A fresh thrall appears close to its caster. */
	static final int CAST_RADIUS = 3;
	/** Our thrall follows us, so when we look for it by position it is close, but not always adjacent. */
	static final int REACQUIRE_RADIUS = 10;

	enum Mode
	{
		/** Our varbit just turned on: look for the thrall that spawned with it. */
		FRESH_CAST,
		/** Varbit on but no thrall claimed (missed cast, scene reload, left render range). */
		REACQUIRE,
		/** We teleported away from our thrall: only accept one that is interacting with us. */
		INTERACTING_ONLY,
	}

	@Value
	static class Candidate<T>
	{
		T thrall;
		/** Chebyshev tile distance from the local player. */
		int distance;
		boolean interactingWithMe;
		boolean interactingWithOtherPlayer;
		/** Another player stands at least as close to this thrall as we do. */
		boolean otherPlayerAsClose;
		/** Ticks between the varbit turning on and this thrall appearing; negative if it appeared first. */
		int spawnTickOffset;
		ThrallType type;
	}

	private ThrallClaim()
	{
	}

	/**
	 * The type of thrall our latest cast raised, or null when it isn't known:
	 * no cast seen since the plugin started, or the varbit turned on with no
	 * cast of ours just before it (a missed cast graphic, which may have been
	 * another type). Players switch type between rooms and raids, so this is
	 * always the latest cast, never a preference.
	 */
	@Nullable
	static ThrallType latestCastType(@Nullable ThrallType castType, int castTick, int varbitOnTick)
	{
		if (castType == null || castTick < 0)
		{
			return null;
		}
		// The varbit turns on about 5 ticks after the cast (measured).
		if (varbitOnTick >= 0 && varbitOnTick - castTick > CAST_WINDOW_BEFORE_TICKS)
		{
			return null;
		}
		return castType;
	}

	/**
	 * A thrall claimed without our cast graphic on its spawn tick (reacquired,
	 * found again, judged at the varbit) must be the type our latest cast
	 * raised, so a teammate's thrall of another type is never taken. With the
	 * latest cast unknown, any type will do.
	 */
	static boolean fitsLatestCast(@Nullable ThrallType latestCast, ThrallType type)
	{
		return latestCast == null || latestCast == type;
	}

	/** A thrall spawning right after our cast graphic is ours if it's the type cast, beside us. */
	static boolean fitsCastAtSpawn(@Nullable ThrallType castType, ThrallType type, int distance)
	{
		return castType != null && castType == type && distance <= CAST_RADIUS;
	}

	/**
	 * We already hold a thrall claimed from this same cast, and another of the
	 * cast's type appears beside us (someone near us cast the same spell at
	 * about the same time). Take the newcomer only if it fits our cast better:
	 * ours spawns in the tick of our cast graphic (measured in game), so the
	 * spawn closer to the cast wins, then the nearer one; a tie keeps the one
	 * we hold. Offsets are spawn tick minus cast tick.
	 */
	static boolean replacesCastClaim(int heldSpawnOffset, int heldDistance, int newSpawnOffset, int newDistance)
	{
		int held = Math.abs(heldSpawnOffset);
		int fresh = Math.abs(newSpawnOffset);
		if (fresh != held)
		{
			return fresh < held;
		}
		return newDistance < heldDistance;
	}

	static boolean isInCastWindow(int spawnTickOffset)
	{
		return spawnTickOffset >= -CAST_WINDOW_BEFORE_TICKS && spawnTickOffset <= CAST_WINDOW_AFTER_TICKS;
	}

	/** Pick our thrall; {@code latestCast} is {@link #latestCastType}, null when unknown. */
	@Nullable
	static <T> Candidate<T> pick(List<Candidate<T>> candidates, Mode mode, @Nullable ThrallType latestCast)
	{
		List<Candidate<T>> eligible = candidates.stream()
			.filter(c -> !c.isInteractingWithOtherPlayer())
			.filter(c -> fitsLatestCast(latestCast, c.getType()))
			.collect(Collectors.toList());

		Candidate<T> following = eligible.stream()
			.filter(Candidate::isInteractingWithMe)
			.min(Comparator.comparingInt(Candidate::getDistance))
			.orElse(null);
		if (following != null || mode == Mode.INTERACTING_ONLY)
		{
			return following;
		}

		if (mode == Mode.FRESH_CAST)
		{
			List<Candidate<T>> spawnedWithCast = eligible.stream()
				.filter(c -> isInCastWindow(c.getSpawnTickOffset()))
				.filter(c -> c.getDistance() <= CAST_RADIUS)
				.collect(Collectors.toList());
			if (spawnedWithCast.size() == 1)
			{
				// One thrall appeared next to us as our varbit turned on: that's
				// ours even if someone else is stacked on the same tile.
				return spawnedWithCast.get(0);
			}
			// Several casts landed together (a stacked raid lobby): prefer the
			// one nobody else is as close to, then the nearest, then the one
			// whose spawn lines up best with our varbit.
			return spawnedWithCast.stream()
				.min(Comparator.<Candidate<T>, Boolean>comparing(Candidate::isOtherPlayerAsClose)
					.thenComparingInt(Candidate::getDistance)
					.thenComparingInt(c -> Math.abs(c.getSpawnTickOffset() - EXPECTED_SPAWN_OFFSET)))
				.orElse(null);
		}

		// REACQUIRE: a thrall stays beside its owner, so one that is nearer to
		// us than to anybody else is ours.
		return eligible.stream()
			.filter(c -> c.getDistance() <= REACQUIRE_RADIUS)
			.filter(c -> !c.isOtherPlayerAsClose())
			.min(Comparator.comparingInt(Candidate::getDistance))
			.orElse(null);
	}
}

package com.thrallinone;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.client.eventbus.Subscribe;

/**
 * Picks out the damage our thrall deals and hands each hit to
 * {@link ThrallFights}, which splits it into fights.
 *
 * <p>The game shows our thrall's hitsplats as ours (the same "mine" type as
 * our own hits), so they can't be told apart by type. Instead every attack
 * our thrall makes is noted when it starts: the projectile it fires (ghostly
 * and skeletal thralls) or its attack animation (zombified thralls). Each
 * attack expects one hitsplat of 0 to 3 (thralls always hit, max 3) on its
 * target within a tick of when it should land, and the first such hitsplat
 * is counted as the thrall's. If one of our own hits of 3 or less lands on
 * the same target in the same tick, the count can be off by that hit.
 */
@Slf4j
@Singleton
public class ThrallDamage
{
	private static final int THRALL_MAX_HIT = 3;
	/** Client cycles per game tick. */
	private static final int CYCLES_PER_TICK = 30;

	private final Client client;
	private final ThrallTracker tracker;
	private final ThrallFights fights;

	private final List<ExpectedHit> expected = new ArrayList<>();
	/** Small hitsplats of ours this tick that no thrall attack has claimed (yet). */
	private final List<SeenHitsplat> unclaimed = new ArrayList<>();
	private final Set<Projectile> seenProjectiles = Collections.newSetFromMap(new IdentityHashMap<>());

	/** The last NPC we attacked; our thrall keeps attacking it after we stop. */
	@Nullable
	private Actor lastPlayerTarget;
	/** The thrall whose animations we last saw, and the tick we first saw it. */
	private NPC lastThrall;
	private int lastThrallSince;

	@Inject
	ThrallDamage(Client client, ThrallTracker tracker, ThrallFights fights)
	{
		this.client = client;
		this.tracker = tracker;
		this.fights = fights;
	}

	void reset()
	{
		expected.clear();
		unclaimed.clear();
		seenProjectiles.clear();
		lastThrall = null;
		lastPlayerTarget = null;
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		Projectile projectile = event.getProjectile();
		NPC thrall = tracker.getOwned();
		// Thrall projectiles don't carry their source NPC, so a projectile is
		// tied to our thrall by starting on its tile.
		if (thrall == null || seenProjectiles.contains(projectile) || !ThrallProjectiles.startsAt(projectile, thrall))
		{
			return;
		}
		seenProjectiles.add(projectile);

		if (projectile.getSourceActor() != thrall && !ThrallProjectiles.isThrallProjectile(projectile.getId()))
		{
			// Something else fired from our thrall's tile (us standing on it,
			// or a cosmetic thrall projectile we don't know yet).
			log.debug("Projectile {} started at our thrall but isn't a known thrall projectile (source {})",
				projectile.getId(), projectile.getSourceActor() == null ? "none" : projectile.getSourceActor().getName());
			return;
		}

		// Measured in game: the hitsplat reaches the client in the tick the
		// bolt is fired (it is only drawn when the bolt lands), or a tick
		// later from further away.
		Actor target = targetOf(thrall, projectile.getTargetActor());
		int tick = client.getTickCount();
		int ticksToLand = (projectile.getRemainingCycles() + CYCLES_PER_TICK - 1) / CYCLES_PER_TICK;
		log.debug("Thrall projectile {} at {} from tick {}, lands about tick {}",
			projectile.getId(), nameOf(target), tick, tick + ticksToLand);
		expect(target, ThrallType.of(thrall.getId()), tick, tick + ticksToLand + 1);
	}

	/**
	 * Who our thrall is attacking. Thralls attack whatever we attack, and a
	 * zombified thrall never reports a target, so fall back to our own target,
	 * then the last NPC we attacked (the thrall keeps going after we stop).
	 * Null means unknown: the attack then matches a hitsplat on any NPC.
	 */
	@Nullable
	private Actor targetOf(NPC thrall, @Nullable Actor reported)
	{
		if (reported != null)
		{
			return reported;
		}
		if (thrall.getInteracting() != null)
		{
			return thrall.getInteracting();
		}
		Player me = client.getLocalPlayer();
		if (me != null && me.getInteracting() instanceof NPC)
		{
			return me.getInteracting();
		}
		return lastPlayerTarget;
	}

	private static String nameOf(@Nullable Actor actor)
	{
		return actor == null ? "an unknown NPC" : actor.getName();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		NPC thrall = tracker.getOwned();
		if (thrall == null || event.getActor() != thrall || thrall.getAnimation() == -1)
		{
			return;
		}

		int tick = client.getTickCount();
		if (thrall != lastThrall)
		{
			lastThrall = thrall;
			lastThrallSince = tick;
		}
		// Its first animation is rising from the ground, not an attack.
		if (tick == lastThrallSince || ThrallType.of(thrall.getId()) != ThrallType.MELEE)
		{
			return;
		}

		// Measured in game: a zombified thrall attacks every 4 ticks without
		// reporting a target, and the hitsplat follows a tick later.
		Actor target = targetOf(thrall, null);
		log.debug("Thrall attack animation {} at {} on tick {}", thrall.getAnimation(), nameOf(target), tick);
		// Never the same tick: a hitsplat arriving with the animation is our own hit.
		expect(target, ThrallType.MELEE, tick + 1, tick + 2);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Hitsplat hitsplat = event.getHitsplat();
		Actor target = event.getActor();
		int tick = client.getTickCount();
		if (log.isDebugEnabled() && expected.stream().anyMatch(hit -> hit.target == null || hit.target == target))
		{
			log.debug("Hitsplat {} (type {}, mine {}) on {} at tick {}",
				hitsplat.getAmount(), hitsplat.getHitsplatType(), hitsplat.isMine(), target.getName(), tick);
		}
		if (!hitsplat.isMine() || hitsplat.getAmount() > THRALL_MAX_HIT || target == client.getLocalPlayer())
		{
			return;
		}

		for (Iterator<ExpectedHit> it = expected.iterator(); it.hasNext(); )
		{
			ExpectedHit hit = it.next();
			if ((hit.target == null || hit.target == target) && tick >= hit.fromTick && tick <= hit.toTick)
			{
				it.remove();
				record(hitsplat.getAmount(), target, tick, hit.type);
				return;
			}
		}

		// The thrall's attack may show up later in this same tick; keep the
		// hitsplat until the tick ends so that attack can still claim it.
		if (tracker.getOwned() != null)
		{
			unclaimed.add(new SeenHitsplat(target, hitsplat.getAmount(), tick));
		}
	}

	/**
	 * Note an attack by our thrall, or count it straight away if its hitsplat already arrived this tick.
	 * The thrall's type is taken now: it may run out before the hit lands.
	 */
	private void expect(@Nullable Actor target, @Nullable ThrallType type, int fromTick, int toTick)
	{
		for (Iterator<SeenHitsplat> it = unclaimed.iterator(); it.hasNext(); )
		{
			SeenHitsplat seen = it.next();
			if ((target == null || seen.target == target) && seen.tick >= fromTick)
			{
				it.remove();
				record(seen.amount, seen.target, seen.tick, type);
				return;
			}
		}
		expected.add(new ExpectedHit(target, type, fromTick, toTick));
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player me = client.getLocalPlayer();
		if (me != null && me.getInteracting() instanceof NPC)
		{
			lastPlayerTarget = me.getInteracting();
		}
		else if (lastPlayerTarget instanceof NPC && ((NPC) lastPlayerTarget).isDead())
		{
			lastPlayerTarget = null;
		}

		int tick = client.getTickCount();
		expected.removeIf(hit -> hit.toTick < tick);
		unclaimed.removeIf(seen -> seen.tick < tick);
		seenProjectiles.removeIf(projectile -> projectile.getRemainingCycles() <= 0);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
				reset();
				break;
			case HOPPING:
			case LOADING:
				expected.clear();
				unclaimed.clear();
				lastPlayerTarget = null;
				seenProjectiles.clear();
				break;
			default:
				break;
		}
	}

	private void record(int damage, Actor target, int tick, @Nullable ThrallType type)
	{
		log.debug("Thrall hit {} on {} at tick {}", damage, target.getName(), tick);
		fights.onThrallHit(damage, tick, type);
	}

	private static final class ExpectedHit
	{
		final Actor target;
		@Nullable
		final ThrallType type;
		final int fromTick;
		final int toTick;

		ExpectedHit(Actor target, @Nullable ThrallType type, int fromTick, int toTick)
		{
			this.target = target;
			this.type = type;
			this.fromTick = fromTick;
			this.toTick = toTick;
		}
	}

	private static final class SeenHitsplat
	{
		final Actor target;
		final int amount;
		final int tick;

		SeenHitsplat(Actor target, int amount, int tick)
		{
			this.target = target;
			this.amount = amount;
			this.tick = tick;
		}
	}
}

package com.thrallinone;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Labels each thrall with the tracker's verdict so ownership detection can be
 * checked in a crowd. Off by default.
 */
class ThrallDebugOverlay extends Overlay
{
	private static final Color MINE = new Color(0, 255, 255);
	private static final Color OTHER = new Color(200, 200, 200);

	private final Client client;
	private final ThrallTracker tracker;
	private final ThrallInOneConfig config;

	@Inject
	ThrallDebugOverlay(Client client, ThrallTracker tracker, ThrallInOneConfig config)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.debugLabels())
		{
			return null;
		}

		Player me = client.getLocalPlayer();
		for (NPC npc : tracker.getThralls())
		{
			boolean mine = tracker.isOwned(npc);
			String label = (mine ? "MINE: " + tracker.getClaimReason() : "other")
				+ " | " + describe(npc.getInteracting(), me);
			// Above the timer text, which sits at the usual overhead height.
			Point location = npc.getCanvasTextLocation(graphics, label, npc.getLogicalHeight() + 80);
			if (location != null)
			{
				OverlayUtil.renderTextLocation(graphics, location, label, mine ? MINE : OTHER);
			}
		}

		if (me != null)
		{
			String state = tracker.isLeftBehind() ? "thrall left behind"
				: !tracker.hasActiveThrall() ? "no thrall out"
				: tracker.getOwned() == null ? "thrall out, not found" : "thrall found";
			OverlayUtil.renderActorOverlay(graphics, me, "Thrall In One: " + state, OTHER);
		}
		return null;
	}

	private static String describe(Actor target, Player me)
	{
		if (target == null)
		{
			return "idle";
		}
		if (target == me)
		{
			return "-> you";
		}
		return (target instanceof Player ? "-> player " : "-> ") + target.getName();
	}
}

package com.thrallinone;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

/**
 * Splits our combat into fights and keeps their stats: uptime, the thrall's
 * share of our damage and its DPS, added up for the session (shown in the
 * sidebar panel) and fed into the saved records. Summons and their cost are
 * counted by {@link ThrallSummons}, driven from here.
 *
 * <p>A fight starts with our first hitsplat on an NPC (ours or our thrall's)
 * and ends when the NPC we hit most dies and nothing else is hit for a few
 * ticks, when we die, when we leave the raid it started in, or when nothing
 * has been hit for the "Fight ends after" time, which the reminders use too. Fights are only saved while we use
 * thralls: our thrall was out during the fight, or in the 10 minutes before
 * it, so a fight where we forgot to cast still counts against uptime. A fight
 * that starts where thralls can't be summoned (Nightmare Zone, a boat, a
 * learned spot) counts only if our thrall was out during it.
 */
@Slf4j
@Singleton
public class ThrallFights
{
	/** Ticks after the main target dies with no other hits before the fight ends. */
	private static final int DEATH_GRACE_TICKS = 3;
	/** A fight counts if our thrall was out this long before it (10 minutes). */
	private static final int RECENT_THRALL_TICKS = 1000;

	private final Client client;
	private final ThrallTracker tracker;
	private final ThrallInOneConfig config;
	private final ThrallStatsStore store;
	private final ThrallSummons summons;
	private final NoSummonTracker noSummon;

	/** The fight going on now, or null. */
	@Nullable
	private Fight current;
	/** Finished fights this login session that count (see the class comment). */
	private FightTotals session = new FightTotals();

	private int lastThrallOutTick = -1;
	private boolean thrallOutBeforeFight;
	private int targetDiedTick = -1;
	/** Tick we last died, or -1. */
	private int diedTick = -1;

	/** Where updates go; null while the sidebar panel is off. */
	@Nullable
	private volatile ThrallPanel panel;
	/** The session or the saved records changed since the panel last got them. */
	private boolean sessionChanged;
	private boolean recordsChanged;

	@Inject
	ThrallFights(Client client, ThrallTracker tracker, ThrallInOneConfig config, ThrallStatsStore store,
		ThrallSummons summons, NoSummonTracker noSummon)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.store = store;
		this.summons = summons;
		this.noSummon = noSummon;
	}

	/** Start afresh and load the account's records. Client thread. */
	void reset()
	{
		current = null;
		session = new FightTotals();
		lastThrallOutTick = -1;
		targetDiedTick = -1;
		diedTick = -1;
		summons.reset();
		store.load();
		sessionChanged = true;
		recordsChanged = true;
		pushToPanel();
	}

	/** Save the fight in progress, if any (the plugin is stopping). Client thread. */
	void stop()
	{
		if (current != null)
		{
			finish();
		}
	}

	void setPanel(@Nullable ThrallPanel panel)
	{
		this.panel = panel;
		sessionChanged = true;
		recordsChanged = true;
	}

	/** Push everything to a freshly shown panel. Client thread. */
	void refreshPanel()
	{
		sessionChanged = true;
		recordsChanged = true;
		pushToPanel();
	}

	/** Clear the account's saved records. Client thread. */
	void resetRecords()
	{
		store.reset();
		recordsChanged = true;
		pushToPanel();
	}

	private boolean thrallOut()
	{
		return tracker.hasActiveThrall() || tracker.getOwned() != null;
	}

	@Nullable
	private ThrallTier ownedTier()
	{
		NPC owned = tracker.getOwned();
		return owned == null ? null : ThrallTier.of(owned.getId());
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor target = event.getActor();
		int tick = client.getTickCount();
		if (!event.getHitsplat().isMine() || !(target instanceof NPC) || !isNamed(target.getName()) || justDied(tick))
		{
			return;
		}
		fightAt(tick).hit(tick, target, target.getName(), event.getHitsplat().getAmount());
	}

	/**
	 * Unnamed NPCs are hidden helpers we never attack, like the body behind
	 * Ocellus's second phase. Our hitsplats on them are bookkeeping, not damage,
	 * and would otherwise count as fights of their own.
	 */
	static boolean isNamed(@Nullable String name)
	{
		return name != null && !name.isEmpty() && !"null".equals(name);
	}

	/**
	 * One of our hitsplats that {@link ThrallDamage} matched to our thrall's attack,
	 * with the type of the thrall that attacked (it may have run out since).
	 */
	void onThrallHit(int damage, int tick, @Nullable ThrallType type)
	{
		if (justDied(tick))
		{
			return;
		}
		fightAt(tick).thrallHit(tick, type, damage);
	}

	/** Hits still landing just after we died belong to the fight that ended with the death. */
	private boolean justDied(int tick)
	{
		return diedTick >= 0 && tick >= diedTick && tick - diedTick <= DEATH_GRACE_TICKS;
	}

	/** The fight going on, starting one if there is none. */
	private Fight fightAt(int tick)
	{
		if (current == null)
		{
			current = new Fight(tick);
			current.setRaid(BossKey.current(client));
			boolean recentThrall = lastThrallOutTick >= 0 && tick >= lastThrallOutTick && tick - lastThrallOutTick <= RECENT_THRALL_TICKS;
			// Where no thrall can be summoned, not having one out isn't a lapse.
			thrallOutBeforeFight = thrallOut() || recentThrall && !noSummon.isNoSummonHere();
			targetDiedTick = -1;
			log.debug("Fight started at tick {} (raid {}, template region {})", tick, current.getRaid(), BossKey.templateRegion(client));
		}
		return current;
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			diedTick = client.getTickCount();
			if (current != null)
			{
				log.debug("We died at tick {}", diedTick);
				finish();
				pushToPanel();
			}
		}
		else if (current != null && event.getActor() == current.getMainTarget())
		{
			targetDiedTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		boolean thrallOut = thrallOut();
		if (thrallOut)
		{
			lastThrallOutTick = tick;
		}
		ThrallSummons.Change change = summons.tick(tick);
		if (change != ThrallSummons.Change.NONE)
		{
			sessionChanged = true;
		}
		if (change == ThrallSummons.Change.SUMMON)
		{
			recordsChanged = true;
		}

		if (current != null && leftRaid())
		{
			// Teleported out or wiped: the ticks outside the raid aren't part of the fight.
			log.debug("Left {} at tick {}; fight over", current.getRaid(), tick);
			finish();
		}
		if (current != null)
		{
			current.tick(tick, thrallOut, ownedTier());
			if (fightOver(tick))
			{
				finish();
			}
		}

		pushToPanel();
	}

	/** The fight started in a raid and we're no longer in it. */
	private boolean leftRaid()
	{
		String raid = current.getRaid();
		return raid != null && !raid.equals(BossKey.current(client));
	}

	private boolean fightOver(int tick)
	{
		int sinceLastHit = tick - current.getLastHitTick();
		if (sinceLastHit > Fight.secondsToTicks(config.combatTimeoutSeconds()))
		{
			return true;
		}
		if (targetDiedTick >= 0 && tick - targetDiedTick >= DEATH_GRACE_TICKS)
		{
			// A hit landing a tick after the death was already on its way.
			if (current.getLastHitTick() <= targetDiedTick + 1)
			{
				return true;
			}
			// We moved straight on to another target: the fight carries on.
			targetDiedTick = -1;
		}
		return false;
	}

	private void finish()
	{
		Fight fight = current;
		current = null;
		targetDiedTick = -1;
		FightRecord record = fight.toRecord();
		boolean counts = thrallOutBeforeFight || fight.getThrallTicks() > 0;
		log.debug("Fight ended: {} ({} ticks, thrall out {}), thrall {} of {} damage, saved {}",
			record.getBoss(), record.getTicks(), record.getThrallTicks(), record.getThrallDamage(),
			record.getThrallDamage() + record.getOwnDamage(), counts);
		if (!counts)
		{
			return;
		}

		session.add(record);
		sessionChanged = true;
		store.getRecords().addFight(record);
		store.save();
		recordsChanged = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
				if (current != null)
				{
					finish();
				}
				// The tick count can start again after this.
				diedTick = -1;
				summons.loggedOut(event.getGameState() == GameState.LOGIN_SCREEN);
				if (event.getGameState() == GameState.LOGIN_SCREEN)
				{
					session = new FightTotals();
					sessionChanged = true;
					lastThrallOutTick = -1;
				}
				pushToPanel();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		store.load();
		recordsChanged = true;
		pushToPanel();
	}

	/**
	 * Send the panel what changed: the session when a fight ends or we cast,
	 * the records when they're saved. Copies are made here, on the client thread.
	 */
	private void pushToPanel()
	{
		ThrallPanel target = panel;
		if (target == null)
		{
			return;
		}
		if (sessionChanged)
		{
			sessionChanged = false;
			FightTotals sessionCopy = new FightTotals(session);
			int casts = summons.getSessionCasts();
			SwingUtilities.invokeLater(() -> target.showSession(sessionCopy, casts));
		}
		if (recordsChanged)
		{
			recordsChanged = false;
			ThrallRecords records = store.copy();
			SwingUtilities.invokeLater(() -> target.showRecords(records));
		}
	}
}

package com.thrallinone;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * Settings, in the order players change them most, with Title Case names.
 */
@ConfigGroup(ThrallInOneConfig.GROUP)
public interface ThrallInOneConfig extends Config
{
	String GROUP = "thrallinone";

	// Loose item first: RuneLite sorts sectionless items in among the sections by position.

	@ConfigItem(
		keyName = "sidebarPanel",
		name = "Sidebar Button",
		description = "Show Thrall In One's button in the sidebar: this session, casts left, lifetime stats,"
			+ " raids, and what your summons cost",
		position = 0
	)
	default boolean sidebarPanel()
	{
		return true;
	}

	@ConfigSection(
		name = "Thralls",
		description = "Which thralls are drawn, and their colors",
		position = 1
	)
	String thrallsSection = "thralls";

	@ConfigSection(
		name = "Outline",
		description = "Outline width, and which thralls are colored by type",
		position = 2
	)
	String outlineSection = "outline";

	@ConfigSection(
		// "»" reads as part of Outline above: RuneLite can't nest sections, and
		// RuneScape Bold has no "↳".
		name = "» Your Type Colors",
		description = "Outline colors for your thrall by type, used while Color by Type is Yours or Both",
		position = 3,
		closedByDefault = true
	)
	String yourTypeColorsSection = "yourTypeColors";

	@ConfigSection(
		name = "» Others' Type Colors",
		description = "Outline colors for other players' thralls by type, used while Color by Type is Others or Both",
		position = 4,
		closedByDefault = true
	)
	String othersTypeColorsSection = "othersTypeColors";

	@ConfigSection(
		name = "Timer",
		description = "Time left on your thrall, shown above it",
		position = 5
	)
	String timerSection = "timer";

	@ConfigSection(
		name = "Reminders",
		description = "Reminders when your thrall runs out or can't be cast",
		position = 6
	)
	String remindersSection = "reminders";

	@ConfigSection(
		name = "Casts Left",
		description = "Casts you have runes for, shown in the sidebar panel",
		position = 7
	)
	String castsSection = "casts";

	// Thralls

	@ConfigItem(
		keyName = "ownShow",
		name = "Your Thrall",
		description = "How your thrall is drawn: with an outline, outline only, as normal, or not at all",
		section = thrallsSection,
		position = 0
	)
	default OwnThrallShow ownShow()
	{
		return OwnThrallShow.OUTLINE_ONLY;
	}

	@Alpha
	@ConfigItem(
		keyName = "ownColor",
		name = "Your Color",
		description = "Outline color for your thrall. Unused while Color by Type (Outline section) is Yours or Both",
		section = thrallsSection,
		position = 1
	)
	default Color ownColor()
	{
		return new Color(255, 200, 0, 200);
	}

	@ConfigItem(
		keyName = "othersShow",
		name = "Other Thralls",
		description = "How other players' thralls are drawn. While their models are hidden (Hidden or Outline Only),"
			+ " the bolts and spells they fire are hidden too",
		section = thrallsSection,
		position = 2
	)
	default OthersThrallShow othersShow()
	{
		return OthersThrallShow.HIDDEN;
	}

	@Alpha
	@ConfigItem(
		keyName = "othersColor",
		name = "Others' Color",
		description = "Outline color for other players' thralls. Unused while Color by Type (Outline section) is Others or Both",
		section = thrallsSection,
		position = 3
	)
	default Color othersColor()
	{
		return new Color(255, 255, 255, 90);
	}

	@ConfigItem(
		keyName = "muteThralls",
		name = "Mute Attacks",
		description = "Silence thralls' attack sounds: other players' thralls only, or every thrall",
		section = thrallsSection,
		position = 4
	)
	default MuteThralls muteThralls()
	{
		return MuteThralls.OFF;
	}

	@ConfigItem(
		keyName = "muteSummonSounds",
		name = "Mute Summon Sounds",
		description = "Silence thralls being raised (the Resurrect spell's sound) and returning to the grave,"
			+ " including the Leagues imps' arrivals and departures",
		section = thrallsSection,
		position = 5
	)
	default boolean muteSummonSounds()
	{
		return false;
	}

	// Outline

	@Range(min = 1, max = 50)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Width",
		description = "Outline width",
		section = outlineSection,
		position = 0
	)
	default int outlineWidth()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "colorByTypeMode",
		name = "Color by Type",
		description = "Color outlines by the thrall's type (Mage, Ranged, Melee) instead of Your Color or Others' Color:"
			+ " for your thrall, other players' thralls, or both. The colors are in the Type Colors sections below",
		section = outlineSection,
		position = 1
	)
	default ColorByType colorByType()
	{
		return ColorByType.YOURS;
	}

	// Your Type Colors

	@Alpha
	@ConfigItem(
		keyName = "magicColor",
		name = "Mage",
		description = "Outline color for your mage thrall (ghostly, or the magic imp and Deadman cosmetics)",
		section = yourTypeColorsSection,
		position = 0
	)
	default Color magicColor()
	{
		return new Color(80, 160, 255, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "rangedColor",
		name = "Ranged",
		description = "Outline color for your ranged thrall (skeletal, or the ranged imp and Deadman cosmetics)",
		section = yourTypeColorsSection,
		position = 1
	)
	default Color rangedColor()
	{
		return new Color(90, 220, 90, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "meleeColor",
		name = "Melee",
		description = "Outline color for your melee thrall (zombified, or the melee imp and Deadman cosmetics)",
		section = yourTypeColorsSection,
		position = 2
	)
	default Color meleeColor()
	{
		return new Color(230, 70, 70, 220);
	}

	// Others' Type Colors: the same hues as yours, as faint as Others' Color.

	@Alpha
	@ConfigItem(
		keyName = "othersMagicColor",
		name = "Mage",
		description = "Outline color for other players' mage thralls",
		section = othersTypeColorsSection,
		position = 0
	)
	default Color othersMagicColor()
	{
		return new Color(80, 160, 255, 90);
	}

	@Alpha
	@ConfigItem(
		keyName = "othersRangedColor",
		name = "Ranged",
		description = "Outline color for other players' ranged thralls",
		section = othersTypeColorsSection,
		position = 1
	)
	default Color othersRangedColor()
	{
		return new Color(90, 220, 90, 90);
	}

	@Alpha
	@ConfigItem(
		keyName = "othersMeleeColor",
		name = "Melee",
		description = "Outline color for other players' melee thralls",
		section = othersTypeColorsSection,
		position = 2
	)
	default Color othersMeleeColor()
	{
		return new Color(230, 70, 70, 90);
	}

	// Timer. Each feature section opens with its own Enabled tick, on by default.

	@ConfigItem(
		keyName = "timerEnabled",
		name = "Enabled",
		description = "Show the time left above your thrall",
		section = timerSection,
		position = 0
	)
	default boolean timerEnabled()
	{
		return true;
	}

	@Range(min = ThrallTimerOverlay.MIN_FONT_SIZE, max = ThrallTimerOverlay.MAX_FONT_SIZE)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "timerFontSize",
		name = "Font Size",
		description = "Size of the time left. 16 matches the game's own text; multiples of 16 stay the sharpest",
		section = timerSection,
		position = 1
	)
	default int timerFontSize()
	{
		return ThrallTimerOverlay.BASE_FONT_SIZE;
	}

	@Range(max = 60)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "timerWarnSeconds",
		name = "Warn At",
		description = "Turn the timer to the warning color with this many seconds left",
		section = timerSection,
		position = 2
	)
	default int timerWarnSeconds()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "timerColor",
		name = "Color",
		description = "Color of the time left",
		section = timerSection,
		position = 3
	)
	default Color timerColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "timerWarnColor",
		name = "Warning Color",
		description = "Color of the time left near the end",
		section = timerSection,
		position = 4
	)
	default Color timerWarnColor()
	{
		// The orange the game uses for interface highlights.
		return new Color(255, 152, 31);
	}

	// Reminders

	@ConfigItem(
		keyName = "remindersEnabled",
		name = "Enabled",
		description = "Turn every reminder below on or off at once. Fight Ends After still applies to fight stats",
		section = remindersSection,
		position = 0
	)
	default boolean remindersEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "recastBox",
		name = "Recast Box",
		description = "A \"Recast Thrall\" box above the chatbox while you fight without a thrall",
		section = remindersSection,
		position = 1
	)
	default RecastBox recastBox()
	{
		return RecastBox.STEADY;
	}

	@ConfigItem(
		keyName = "expiredBoxColor",
		name = "Box Color",
		description = "Fill color of the Recast Thrall box (unused while Recast Box is Off)",
		section = remindersSection,
		position = 2
	)
	default Color expiredBoxColor()
	{
		return new Color(156, 43, 36);
	}

	@ConfigItem(
		keyName = "summonCheck",
		name = "Spellbook Warning",
		description = "An amber \"Not on the Arceuus Spellbook\" box when you're not on the Arceuus spellbook,"
			+ " while fighting within 10 minutes of having a thrall out",
		section = remindersSection,
		position = 3
	)
	default boolean summonCheck()
	{
		return false;
	}

	@ConfigItem(
		keyName = "bookWarning",
		name = "Book of the Dead Warning",
		description = "An amber \"No Book of the Dead\" box when you don't have the Book of the Dead with you,"
