package com.thrallinone;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Provider;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.Projectile;
import net.runelite.api.Renderable;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Thrall In One",
	description = "Tells your own Arceuus thrall apart from everyone else's: outline yours, hide or tone down theirs",
	tags = {"thrall", "arceuus", "necromancy", "resurrect", "outline", "highlight", "hide"}
)
public class ThrallInOnePlugin extends Plugin implements RenderCallback
{
	@Inject
	private ThrallInOneConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ThrallTracker tracker;

	@Inject
	private ThrallOutlineOverlay outlineOverlay;

	// Ownership labels exist only in developer mode (./gradlew run), toggled with ::thralllabels.
	@Inject
	private ThrallDebugOverlay debugOverlay;

	@Inject
	@Named("developerMode")
	private boolean developerMode;

	@Inject
	private ThrallTimer timer;

	@Inject
	private ThrallTimerOverlay timerOverlay;

	@Inject
	private ThrallDamage damage;

	@Inject
	private ThrallReminders reminders;

	@Inject
	private ThrallReminderOverlay reminderOverlay;

	@Inject
	private NoSummonTracker noSummon;

	@Inject
	private ThrallCasts casts;

	@Inject
	private ThrallProjectiles projectiles;

	@Inject
	private ThrallSounds sounds;

	// Fight stats and the sidebar panel
	@Inject
	private ThrallFights fights;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Provider<ThrallPanel> panelProvider;

	/** The sidebar button: its own 16 x 16 drawing of icon.png, filled to the edges so it reads at that size. */
	private static final BufferedImage NAV_ICON = ImageUtil.loadImageResource(ThrallInOnePlugin.class, "sidebar_icon.png");

	private ThrallPanel panel;
	private NavigationButton navButton;

	// Read on every rendered entity (client thread), so cached instead of going
	// through the config proxy; written on the Swing thread when settings change.
	private volatile boolean hideOthers;
	private volatile boolean hideOwn;

	@Override
	protected void startUp()
	{
		cacheConfig();
		eventBus.register(tracker);
		eventBus.register(timer);
		eventBus.register(damage);
		eventBus.register(reminders);
		eventBus.register(noSummon);
		eventBus.register(casts);
		eventBus.register(projectiles);
		sounds.reset();
		eventBus.register(sounds);
		clientThread.invoke(() ->
		{
			tracker.start();
			timer.reset();
			damage.reset();
			reminders.reset();
			noSummon.reset();
			casts.reset();
			projectiles.reset();
		});
		renderCallbackManager.register(this);
		overlayManager.add(outlineOverlay);
		overlayManager.add(timerOverlay);
		overlayManager.add(reminderOverlay);
		if (developerMode)
		{
			overlayManager.add(debugOverlay);
		}
		startFightStats();
	}

	private void startFightStats()
	{
		eventBus.register(fights);
		clientThread.invoke(fights::reset);
		ThrallPanel started = panelProvider.get();
		panel = started;
		SwingUtilities.invokeLater(() ->
		{
			// Skip if the plugin was stopped (or restarted) before this ran.
			if (panel == started)
			{
				updateSidebar();
			}
		});
	}

	private void stopFightStats()
	{
		clientThread.invoke(fights::stop);
		eventBus.unregister(fights);
		setPanel(null);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
	}

	/** Add or remove the sidebar button to match the setting. Swing thread. */
	private void updateSidebar()
	{
		boolean show = panel != null && config.sidebarPanel();
		if (show && navButton == null)
		{
			navButton = NavigationButton.builder()
				.tooltip("Thrall In One")
				.icon(NAV_ICON)
				.priority(7)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navButton);
			setPanel(panel);
			panel.refresh();
		}
		else if (!show && navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
			setPanel(null);
		}
	}

	/** Point everything that feeds the sidebar panel at it, or at nothing (null). */
	private void setPanel(@Nullable ThrallPanel target)
	{
		fights.setPanel(target);
		casts.setPanel(target);
	}

	@Override
	protected void shutDown()
	{
		stopFightStats();
		overlayManager.remove(outlineOverlay);
		overlayManager.remove(timerOverlay);
		overlayManager.remove(reminderOverlay);
		overlayManager.remove(debugOverlay);
		renderCallbackManager.unregister(this);
		eventBus.unregister(tracker);
		eventBus.unregister(timer);
		eventBus.unregister(damage);
		eventBus.unregister(reminders);
		eventBus.unregister(noSummon);
		eventBus.unregister(casts);
		eventBus.unregister(projectiles);
		eventBus.unregister(sounds);
		clientThread.invoke(() ->
		{
			tracker.stop();
			projectiles.reset();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ThrallInOneConfig.GROUP.equals(event.getGroup()))
		{
			cacheConfig();
			if ("sidebarPanel".equals(event.getKey()))
			{
				SwingUtilities.invokeLater(this::updateSidebar);
			}
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (developerMode && "thralllabels".equalsIgnoreCase(event.getCommand()))
		{
			configManager.setConfiguration(ThrallInOneConfig.GROUP, "debugLabels", !config.debugLabels());
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		cacheConfig();
	}

	private void cacheConfig()
	{
		hideOthers = !config.othersShow().isModel();
		hideOwn = !config.ownShow().isModel();
	}

	@Override
	public boolean addEntity(Renderable renderable, boolean ui)
	{
		if (renderable instanceof NPC)
		{
			NPC npc = (NPC) renderable;
			if (!ThrallType.isThrall(npc.getId()))
			{
				return true;
			}
			return tracker.isOwned(npc) ? !hideOwn : !hideOthers;
		}

		// Other players' thralls' projectiles go with their models.
		if (renderable instanceof Projectile && hideOthers)
		{
			return !projectiles.isOthers((Projectile) renderable);
		}

		return true;
	}

	@Provides
	ThrallInOneConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ThrallInOneConfig.class);
	}
}

package com.thrallinone;

import lombok.Getter;

/**
 * Why our claimed thrall's NPC went away while the resurrection varbit was
 * still on, and whether it now counts as left behind. Ticks are passed in,
 * so the rules can be unit tested without the client.
 *
 * <p>Every room of The Fractured Archive is its own instance. On entering the
 * next room our thrall stays in the one we left, yet the varbit stays on,
 * even past the thrall's expiry, until the next cast. The game lets us
 * recast meanwhile. So a thrall
 * lost to a scene change that none of ours replaces within
 * {@link #GRACE_TICKS} counts as left behind: not out, whatever the varbit
 * says. A thrall that despawns with its timer at or near zero ran out
 * instead, and nothing else should be claimed in its place. Anything else
 * (it walked out of view) may come back, as before.
 */
final class ThrallLoss
{
	/** A thrall lost to a scene change has this long to come back (it follows us across ordinary map loads). */
	static final int GRACE_TICKS = 5;
	/** Measured: our thrall despawns at expiry with 2 ticks left on the timer, and the varbit clears a tick later. */
	static final int EXPIRY_TICKS = 3;

	enum Kind
	{
		NONE,
		/** Lost while the scene loaded or we teleported: left behind unless it comes back. */
		SCENE_CHANGE,
		/** Despawned with the timer at or near zero: it ran out. */
		EXPIRY,
		/** Despawned for another reason (out of view): it may come back. */
		OUT_OF_VIEW,
	}

	@Getter
	private Kind kind = Kind.NONE;
	/** Tick our thrall was lost, or -1. */
	@Getter
	private int lostTick = -1;
	/** Tick the lost thrall began to count as left behind, or -1. */
	@Getter
	private int leftBehindTick = -1;

	/**
	 * Our claimed thrall went away with the varbit on. A scene change wins
	 * over the timer, which may be a tick or two off: a thrall left behind
	 * just before its expiry isn't coming back either.
	 */
	Kind lost(int tick, boolean sceneChange, int remainingTicks)
	{
		reset();
		lostTick = tick;
		if (sceneChange)
		{
			kind = Kind.SCENE_CHANGE;
		}
		else if (remainingTicks >= 0 && remainingTicks <= EXPIRY_TICKS)
		{
			kind = Kind.EXPIRY;
		}
		else
		{
			kind = Kind.OUT_OF_VIEW;
		}
		return kind;
	}

	/** The scene is loading: a thrall that was out of view is now in another scene. */
	void sceneChanged(int tick)
	{
		if (kind == Kind.OUT_OF_VIEW)
		{
			kind = Kind.SCENE_CHANGE;
			lostTick = tick;
		}
	}

	/** Once a tick; true on the tick the lost thrall starts to count as left behind. */
	boolean tick(int tick)
	{
		if (kind == Kind.SCENE_CHANGE && leftBehindTick < 0 && tick - lostTick >= GRACE_TICKS)
		{
			leftBehindTick = tick;
			return true;
		}
		return false;
	}

	/** A thrall of ours was claimed, the varbit changed, or the tracker reset. */
	void reset()
	{
		kind = Kind.NONE;
		lostTick = -1;
		leftBehindTick = -1;
	}

	boolean isLeftBehind()
	{
		return leftBehindTick >= 0;
	}

	/** Our thrall ran out: claim nothing in its place until the varbit changes or we cast. */
	boolean isExpired()
	{
		return kind == Kind.EXPIRY;
	}
}

package com.thrallinone;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import javax.annotation.Nullable;
import net.runelite.api.gameval.NpcID;

/**
 * Every thrall NPC, with its type and tier, in one table: the Arceuus base
 * thralls, the Leagues imp cosmetics and the Deadman cosmetics (greater
 * thralls).
 */
final class ThrallNpcs
{
	private static final Map<Integer, ThrallType> TYPES;
	private static final Map<Integer, ThrallTier> TIERS;
	/** The id range the table covers, to skip most NPCs without boxing their id (checked every frame). */
	private static final int MIN_ID;
	private static final int MAX_ID;

	static
	{
		Table table = new Table()
			.add(NpcID.ARCEUUS_THRALL_GHOST_LESSER, ThrallType.MAGIC, ThrallTier.LESSER)
			.add(NpcID.ARCEUUS_THRALL_GHOST_SUPERIOR, ThrallType.MAGIC, ThrallTier.SUPERIOR)
			.add(NpcID.ARCEUUS_THRALL_GHOST_GREATER, ThrallType.MAGIC, ThrallTier.GREATER)
			.add(NpcID.THRALL_IMP_MAGIC_LESSER, ThrallType.MAGIC, ThrallTier.LESSER)
			.add(NpcID.THRALL_IMP_MAGIC_SUPERIOR, ThrallType.MAGIC, ThrallTier.SUPERIOR)
			.add(NpcID.THRALL_IMP_MAGIC_GREATER, ThrallType.MAGIC, ThrallTier.GREATER)
			.add(NpcID.DEADMAN_THRALL_GHOSTLY_GREATER_WISP, ThrallType.MAGIC, ThrallTier.GREATER)

			.add(NpcID.ARCEUUS_THRALL_SKELETON_LESSER, ThrallType.RANGED, ThrallTier.LESSER)
			.add(NpcID.ARCEUUS_THRALL_SKELETON_SUPERIOR, ThrallType.RANGED, ThrallTier.SUPERIOR)
			.add(NpcID.ARCEUUS_THRALL_SKELETON_GREATER, ThrallType.RANGED, ThrallTier.GREATER)
			.add(NpcID.THRALL_IMP_RANGED_LESSER, ThrallType.RANGED, ThrallTier.LESSER)
			.add(NpcID.THRALL_IMP_RANGED_SUPERIOR, ThrallType.RANGED, ThrallTier.SUPERIOR)
			.add(NpcID.THRALL_IMP_RANGED_GREATER, ThrallType.RANGED, ThrallTier.GREATER)
			.add(NpcID.DEADMAN_THRALL_SKELETAL_GREATER_PRINCESS, ThrallType.RANGED, ThrallTier.GREATER)

			.add(NpcID.ARCEUUS_THRALL_ZOMBIE_LESSER, ThrallType.MELEE, ThrallTier.LESSER)
			.add(NpcID.ARCEUUS_THRALL_ZOMBIE_SUPERIOR, ThrallType.MELEE, ThrallTier.SUPERIOR)
			.add(NpcID.ARCEUUS_THRALL_ZOMBIE_GREATER, ThrallType.MELEE, ThrallTier.GREATER)
			.add(NpcID.THRALL_IMP_MELEE_LESSER, ThrallType.MELEE, ThrallTier.LESSER)
			.add(NpcID.THRALL_IMP_MELEE_SUPERIOR, ThrallType.MELEE, ThrallTier.SUPERIOR)
			.add(NpcID.THRALL_IMP_MELEE_GREATER, ThrallType.MELEE, ThrallTier.GREATER)
			.add(NpcID.DEADMAN_THRALL_ZOMBIE_GREATER_ZUK, ThrallType.MELEE, ThrallTier.GREATER);
		TYPES = table.types.build();
		TIERS = table.tiers.build();
		MIN_ID = table.min;
		MAX_ID = table.max;
	}

	private ThrallNpcs()
	{
	}

	static boolean isThrall(int npcId)
	{
		return npcId >= MIN_ID && npcId <= MAX_ID && TYPES.containsKey(npcId);
	}

	/** The Leagues imp cosmetics, which have attack sounds of their own. */
	static boolean isImp(int npcId)
	{
		switch (npcId)
		{
			case NpcID.THRALL_IMP_MAGIC_LESSER:
			case NpcID.THRALL_IMP_MAGIC_SUPERIOR:
			case NpcID.THRALL_IMP_MAGIC_GREATER:
			case NpcID.THRALL_IMP_RANGED_LESSER:
			case NpcID.THRALL_IMP_RANGED_SUPERIOR:
			case NpcID.THRALL_IMP_RANGED_GREATER:
			case NpcID.THRALL_IMP_MELEE_LESSER:
			case NpcID.THRALL_IMP_MELEE_SUPERIOR:
			case NpcID.THRALL_IMP_MELEE_GREATER:
				return true;
			default:
				return false;
		}
	}

	@Nullable
	static ThrallType type(int npcId)
	{
		return isThrall(npcId) ? TYPES.get(npcId) : null;
	}

	@Nullable
	static ThrallTier tier(int npcId)
	{
		return isThrall(npcId) ? TIERS.get(npcId) : null;
	}

	private static final class Table
	{
		final ImmutableMap.Builder<Integer, ThrallType> types = ImmutableMap.builder();
		final ImmutableMap.Builder<Integer, ThrallTier> tiers = ImmutableMap.builder();
		int min = Integer.MAX_VALUE;
		int max = Integer.MIN_VALUE;

		Table add(int npcId, ThrallType type, ThrallTier tier)
		{
			types.put(npcId, type);
			tiers.put(npcId, tier);
			min = Math.min(min, npcId);
			max = Math.max(max, npcId);
			return this;
		}
	}
}

package com.thrallinone;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class ThrallOutlineOverlay extends Overlay
{
	/**
	 * How much of the outline's outer band fades (0 to 4).
	 */
	private static final int FEATHER = 3;

	private final ThrallTracker tracker;
	private final ThrallInOneConfig config;
	private final ThrallOutlineRenderer outlineRenderer;

	@Inject
	ThrallOutlineOverlay(ThrallTracker tracker, ThrallInOneConfig config, ThrallOutlineRenderer outlineRenderer)
	{
		this.tracker = tracker;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean outlineOwn = config.ownShow().isOutline();
		boolean outlineOthers = config.othersShow().isOutline();
		if (!outlineOwn && !outlineOthers)
		{
			return null;
		}

		int width = config.outlineWidth();
		int feather = FEATHER;
		ColorByType byType = config.colorByType();
		for (NPC npc : tracker.getThralls())
		{
			if (tracker.isOwned(npc))
			{
				if (outlineOwn)
				{
					outlineRenderer.drawOutline(npc, width, byType.isYours() ? ownTypeColor(npc) : config.ownColor(), feather);
				}
			}
			else if (outlineOthers)
			{
				outlineRenderer.drawOutline(npc, width, byType.isOthers() ? othersTypeColor(npc) : config.othersColor(), feather);
			}
		}
		return null;
	}

	/** Your Type Colors for this thrall's type, or Your Color if its type isn't known. */
	private Color ownTypeColor(NPC npc)
	{
		ThrallType type = ThrallType.of(npc.getId());
		if (type == null)
		{
			return config.ownColor();
		}
		switch (type)
		{
			case MAGIC:
				return config.magicColor();
			case RANGED:
				return config.rangedColor();
			default:
				return config.meleeColor();
		}
	}

	/** Others' Type Colors for this thrall's type, or Others' Color if its type isn't known. */
	private Color othersTypeColor(NPC npc)
	{
		ThrallType type = ThrallType.of(npc.getId());
		if (type == null)
		{
			return config.othersColor();
		}
		switch (type)
		{
			case MAGIC:
				return config.othersMagicColor();
			case RANGED:
				return config.othersRangedColor();
			default:
				return config.othersMeleeColor();
		}
	}
}

