/**
 * The sidebar panel: stats to look at and compare. From the top: lifetime
 * tiles (summoned, prayer drained, gp spent), then boxes for this session,
 * lifetime, Mage / Ranged / Melee, raids and casts left, and a records
 * reset. Each box folds away from its title, and stays folded after a
 * restart. In RuneLite's developer mode, buttons at the very bottom preview
 * each reminder. Updates arrive from {@link ThrallFights} and
 * {@link ThrallCasts} as copies, on the Swing thread; button actions go back
 * on the client thread.
 */
class ThrallPanel extends PluginPanel
{
	/** Box titles: an Arceuus purple, so the panel has its own identity. */
	private static final Color ACCENT = new Color(0xB4, 0x8C, 0xFF);
	/** Casts left below the low mark. */
	private static final Color LOW_COLOR = new Color(230, 150, 30);
	/** Column headings, quieter than labels. */
	private static final Color HEADING_COLOR = new Color(122, 122, 122);
	/** The game's coin stack colors: yellow below 100K, white below 10M, green from 10M. */
	private static final Color GP_YELLOW = new Color(255, 255, 0);
	private static final Color GP_GREEN = new Color(0, 255, 128);
	private static final int ICON_SIZE = 16;
	/** The top trio's icons and values, the biggest things in the panel. */
	private static final int TRIO_ICON_SIZE = 24;
	private static final BufferedImage SUMMONED_ICON = ImageUtil.loadImageResource(ThrallPanel.class, "icon.png");
	private static final Font TRIO_VALUE_FONT = FontManager.getRunescapeBoldFont().deriveFont(24f);
	/** Values in the other tiles (this session, lifetime, casts left). */
	private static final Font TILE_VALUE_FONT = FontManager.getRunescapeBoldFont().deriveFont(20f);
	private static final Font TITLE_FONT = FontManager.getRunescapeBoldFont().deriveFont(18f);
	/** The ⓘ in a box title, in the title purple; lighter while the mouse is over it. */
	private static final ImageIcon INFO_ICON = infoIcon(ACCENT);
	private static final ImageIcon INFO_ICON_HOVER = infoIcon(new Color(0xCF, 0xB4, 0xFF));
	/** Hidden setting: the ids of the folded boxes, comma separated. */
	static final String FOLDED_KEY = "panelFolded";

	private final ClientThread clientThread;
	private final ThrallFights fights;
	private final ThrallCasts casts;
	private final ThrallReminders reminders;
	private final ConfigManager configManager;
	private final Set<String> folded = new LinkedHashSet<>();

	private final Tile summonedTile = new Tile(ColorScheme.DARKER_GRAY_COLOR, true);
	private final Tile prayerTile = new Tile(ColorScheme.DARKER_GRAY_COLOR, true);
	private final Tile gpTile = new Tile(ColorScheme.DARKER_GRAY_COLOR, true);
	private final FoldingBox sessionBox;
	private final FoldingBox lifetimeBox;
	private final FoldingBox typeBox;
	private final FoldingBox raidsBox;
	private final FoldingBox castsBox;
	private final JLabel[] typeIcons = new JLabel[ThrallType.values().length];

	// For the reset confirmation.
	private int savedFights;
	private int savedSummons;

	@Inject
	ThrallPanel(ClientThread clientThread, ThrallFights fights, ThrallCasts casts, ThrallReminders reminders,
		ConfigManager configManager, ItemManager itemManager, SkillIconManager skillIcons, @Named("developerMode") boolean developerMode)
	{
		this.clientThread = clientThread;
		this.fights = fights;
		this.casts = casts;
		this.reminders = reminders;
		this.configManager = configManager;
		readFolded();

		// Narrow sides, so the trio's labels fit at the regular font's size.
		setBorder(new EmptyBorder(10, 8, 10, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new DynamicGridLayout(0, 1, 0, 8));

		JPanel trio = new JPanel(new GridLayout(1, 3, 3, 0));
		trio.setOpaque(false);
		trio.add(summonedTile);
		trio.add(prayerTile);
		trio.add(gpTile);
		add(trio);

		sessionBox = new FoldingBox("session", "This Session");
		lifetimeBox = new FoldingBox("lifetime", "Lifetime");
		typeBox = new FoldingBox("byType", "By Type");
		raidsBox = new FoldingBox("raids", "Raids");
		castsBox = new FoldingBox("casts", "Casts Left");
		castsBox.setInfo("<html>Counted from what you carry right now: the runes in your inventory<br>"
			+ "and rune pouch, plus a staff or tome you're wearing. Your bank<br>"
			+ "isn't counted, so restocking brings the number back up.</html>");
		add(sessionBox);
		add(lifetimeBox);
		add(typeBox);
		add(raidsBox);
		add(castsBox);

		JButton reset = new JButton("Reset Records…");
		reset.setToolTipText("Clear this account's saved thrall records");
		reset.setFocusPainted(false);
		reset.addActionListener(e -> confirmReset());
		add(reset);

		// A testing aid, last so it reads as apart from the panel: shown only in
		// RuneLite's developer mode (./gradlew run), never to players.
		if (developerMode)
		{
			FoldingBox previewBox = new FoldingBox("preview", "Preview Reminder");
			previewBox.setContent(previewButtons());
			add(previewBox);
		}

		// The plugin's own icon (icon.png, as on the Plugin Hub), so the panel matches the sidebar button.
		summonedTile.setIcon(SUMMONED_ICON);
		prayerTile.setIcon(skillIcons.getSkillImage(Skill.PRAYER, false));
		AsyncBufferedImage coins = itemManager.getImage(ItemID.COINS, 10_000, false);
		coins.onLoaded(() -> SwingUtilities.invokeLater(() -> gpTile.setIcon(coins)));
		Skill[] typeSkills = {Skill.MAGIC, Skill.RANGED, Skill.ATTACK};
		for (ThrallType type : ThrallType.values())
		{
			typeIcons[type.ordinal()] = new JLabel(icon(skillIcons.getSkillImage(typeSkills[type.ordinal()], true)));
		}

		showSession(new FightTotals(), 0);
		showCasts(true, -1, ThrallTier.GREATER, false, true);
		showRecords(new ThrallRecords());
	}

	@Override
	public void onActivate()
	{
		refresh();
	}

	/** Ask everything that feeds the panel to send what it has now. Any thread. */
	void refresh()
	{
		clientThread.invoke(() ->
		{
			fights.refreshPanel();
			casts.refreshPanel();
		});
	}

	private JPanel previewButtons()
	{
		JPanel buttons = new JPanel(new GridLayout(0, 2, 4, 4));
		buttons.setOpaque(false);
		for (PreviewReminder reminder : PreviewReminder.values())
		{
			JButton button = new JButton(reminder.getName());
			button.setFocusPainted(false);
			button.setToolTipText("Show " + reminder.getShows() + " for "
				+ ThrallReminders.PREVIEW_MILLIS / 1000 + " seconds, whatever your reminder settings");
			button.addActionListener(e -> clientThread.invoke(() -> reminders.preview(reminder)));
			buttons.add(button);
		}
		return buttons;
	}

	/** Casts left for the tier we'd cast next; -1 before it's counted. Hidden while Casts Left is off. Swing thread. */
	void showCasts(boolean enabled, int left, ThrallTier tier, boolean low, boolean canSummon)
	{
		castsBox.setVisible(enabled);
		JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		content.setOpaque(false);
		Tile tile = new Tile(ColorScheme.DARK_GRAY_COLOR, false);
		// Casts left shows from login, before any fight.
		if (left < 0)
		{
			tile.set("-", "Counted Once Logged In", Color.WHITE, null);
		}
		else
		{
			tile.set(StatsFormat.number(left), tier.getDisplayName() + " Thralls", low ? LOW_COLOR : Color.WHITE,
				tier.getDisplayName() + " thralls the runes you carry pay for, counting the rune pouch,"
					+ " staves and combination runes");
		}
		content.add(tile);
		if (left >= 0 && !canSummon)
		{
			content.add(rows(Arrays.asList(new Row("Can't Summon Now", "",
				"You need the Book of the Dead with you and the Arceuus spellbook", ColorScheme.LIGHT_GRAY_COLOR))));
		}
		castsBox.setContent(content);
	}

	/** This login session's finished fights and casts. Swing thread. */
	void showSession(FightTotals session, int sessionCasts)
	{
		sessionBox.setContent(totalsTiles(session, StatsFormat.shortNumber(sessionCasts), "Casts",
			"Thralls you've cast since you logged in"));
	}

	/** The saved records. Swing thread. */
	void showRecords(ThrallRecords records)
	{
		FightTotals lifetime = records.getLifetime();
		savedFights = lifetime.getFights();
		savedSummons = records.getSummons();

		summonedTile.set(StatsFormat.shortNumber(records.getSummons()), "Summoned", Color.WHITE,
			StatsFormat.number(records.getSummons()) + " thralls summoned on this account");
		prayerTile.set(StatsFormat.shortNumber(records.getPrayerSpent()), "Drained", Color.WHITE,
			StatsFormat.number(records.getPrayerSpent())
				+ " prayer points drained by your Resurrect casts: 2, 4 or 6 for lesser, superior or greater");
		long gp = records.getGpSpent();
		gpTile.set(StatsFormat.shortNumber(gp), "GP Spent", gp >= 10_000_000 ? GP_GREEN : gp >= 100_000 ? Color.WHITE : GP_YELLOW,
			StatsFormat.number(gp) + " gp spent on runes: what your casts' runes were worth on the day of each cast");

		lifetimeBox.setContent(totalsTiles(lifetime, StatsFormat.longDuration(lifetime.getTicks()), "Fight Time",
			"Time in fights that counted, with or without your thrall out"));

		typeBox.setContent(typeTable(records));

		List<Row> raidRows = new ArrayList<>();
		records.getBosses().entrySet().stream()
			.sorted(Comparator.comparingLong(
				(Map.Entry<String, ThrallRecords.BossRecord> raid) -> raid.getValue().getTotals().getThrallDamage()).reversed())
			.forEach(raid -> addRaid(raidRows, raid.getKey(), raid.getValue().getTotals()));
		// Raids only get a box once there's a raid fight to show.
		raidsBox.setVisible(!raidRows.isEmpty());
		raidsBox.setContent(rows(raidRows));
	}

	/** Six tiles: thrall damage, fights, share, uptime, DPS, and one more (casts or fight time). */
	private static JPanel totalsTiles(FightTotals totals, String lastValue, String lastLabel, String lastTooltip)
	{
		JPanel tiles = new JPanel(new GridLayout(0, 2, 4, 4));
		tiles.setOpaque(false);
		Color tileColor = ColorScheme.DARK_GRAY_COLOR;
		tiles.add(new Tile(tileColor, false).set(StatsFormat.shortNumber(totals.getThrallDamage()), "Thrall Damage",
			Color.WHITE, StatsFormat.number(totals.getThrallDamage()) + " damage from your thrall; yours was "
				+ StatsFormat.number(totals.getOwnDamage())));
		tiles.add(new Tile(tileColor, false).set(StatsFormat.shortNumber(totals.getFights()), "Fights", Color.WHITE,
			"Fights that counted: your thrall was out during the fight or in the 10 minutes before it"));
		tiles.add(new Tile(tileColor, false).set(StatsFormat.percent(totals.share()), "Share", Color.WHITE,
			"Your thrall's share of your damage (your hits plus its hits)"));
		tiles.add(new Tile(tileColor, false).set(StatsFormat.percent(totals.uptime()), "Uptime", Color.WHITE,
			"How much of your fights your thrall was out"));
		double expected = totals.expectedDps();
		tiles.add(new Tile(tileColor, false).set(StatsFormat.dps(totals.measuredDps()),
			expected > 0 ? "DPS / " + StatsFormat.dps(expected) : "DPS", Color.WHITE,
			"Measured while your thrall was out / the wiki's figure for its tier (lesser 0.208, superior 0.416, greater 0.625)"));
		tiles.add(new Tile(tileColor, false).set(lastValue, lastLabel, Color.WHITE, lastTooltip));
		return tiles;
	}

	/** Mage / Ranged / Melee: summoned and damage, with each style's skill icon. */
	private JPanel typeTable(ThrallRecords records)
	{
		JPanel table = new JPanel(new GridBagLayout());
		table.setOpaque(false);
		GridBagConstraints c = new GridBagConstraints();
		c.fill = GridBagConstraints.HORIZONTAL;
		c.insets = new Insets(1, 0, 1, 0);
		c.gridy = 0;
		c.gridx = 2;
		table.add(label("Summoned", HEADING_COLOR, SwingConstants.RIGHT), c);
		c.gridx = 3;
		c.insets = new Insets(1, 8, 1, 0);
		table.add(label("Damage", HEADING_COLOR, SwingConstants.RIGHT), c);

		for (ThrallType type : ThrallType.values())
		{
			c.gridy++;
			c.gridx = 0;
			c.weightx = 0;
			c.insets = new Insets(1, 0, 1, 5);
			table.add(typeIcons[type.ordinal()], c);
			c.gridx = 1;
			c.weightx = 1;
			c.insets = new Insets(1, 0, 1, 0);
			table.add(label(type.getDisplayName(), ColorScheme.LIGHT_GRAY_COLOR, SwingConstants.LEFT), c);
			c.gridx = 2;
			c.weightx = 0;
			int summoned = records.getSummonsByType().getOrDefault(type, 0);
			JLabel summonedLabel = label(StatsFormat.shortNumber(summoned), Color.WHITE, SwingConstants.RIGHT);
			summonedLabel.setToolTipText(StatsFormat.number(summoned) + " " + type.getDisplayName().toLowerCase() + " thralls summoned");
			table.add(summonedLabel, c);
			c.gridx = 3;
			c.insets = new Insets(1, 8, 1, 0);
			long damage = records.getDamageByType().getOrDefault(type, 0L);
			JLabel damageLabel = label(StatsFormat.shortNumber(damage), Color.WHITE, SwingConstants.RIGHT);
			damageLabel.setToolTipText(StatsFormat.number(damage) + " damage from your " + type.getDisplayName().toLowerCase() + " thralls");
			table.add(damageLabel, c);
		}
		return table;
	}

	private static void addRaid(List<Row> rows, String name, FightTotals totals)
	{
		rows.add(Row.header(name, StatsFormat.plural(totals.getFights(), "fight", "fights")));
		rows.add(new Row("Thrall Damage", StatsFormat.number(totals.getThrallDamage()), null, Color.WHITE));
		rows.add(new Row("Share / Uptime", StatsFormat.percent(totals.share()) + " / " + StatsFormat.percent(totals.uptime()),
			null, Color.WHITE));
	}

	/** Reset goes through two prompts, the second defaulting to keeping the records. */
	private void confirmReset()
	{
		Object[] first = {"Reset…", "Cancel"};
		int answer = JOptionPane.showOptionDialog(this,
			"Reset thrall records? This clears every saved fight, summon and raid record for this account.",
			"Reset Thrall Records", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, first, first[1]);
		if (answer != 0)
		{
			return;
		}

		Object[] second = {"Reset Everything", "Keep My Records"};
		answer = JOptionPane.showOptionDialog(this,
			"Really reset? " + StatsFormat.plural(savedFights, "fight", "fights") + " and "
				+ StatsFormat.plural(savedSummons, "summon", "summons") + " will be gone for good. This can't be undone.",
			"Really Reset Thrall Records?", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, second, second[1]);
		if (answer == 0)
		{
			clientThread.invoke(fights::resetRecords);
		}
	}

	private void readFolded()
	{
		String saved = configManager.getConfiguration(ThrallInOneConfig.GROUP, FOLDED_KEY);
		if (saved != null && !saved.isEmpty())
		{
			folded.addAll(Arrays.asList(saved.split(",")));
		}
	}

	private void saveFolded()
	{
		if (folded.isEmpty())
		{
			configManager.unsetConfiguration(ThrallInOneConfig.GROUP, FOLDED_KEY);
		}
		else
		{
			configManager.setConfiguration(ThrallInOneConfig.GROUP, FOLDED_KEY, String.join(",", folded));
		}
	}

	private static JLabel label(String text, Color color, int alignment)
	{
		JLabel label = new JLabel(text, alignment);
		label.setFont(FontManager.getRunescapeFont());
		label.setForeground(color);
		return label;
	}

	/**
	 * A circled "i", 16 px: a smooth 1.5 px ring,
	 * and the "i" on whole pixels so it stays crisp.
	 */
	private static ImageIcon infoIcon(Color color)
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(color);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setStroke(new BasicStroke(1.5f));
		g.draw(new Ellipse2D.Double(0.75, 0.75, 14.5, 14.5));
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		g.fillRect(7, 3, 2, 2);
		g.fillRect(7, 6, 2, 7);
		g.dispose();
		return new ImageIcon(image);
	}

	@Nullable
	private static ImageIcon icon(@Nullable BufferedImage image)
	{
		return icon(image, ICON_SIZE);
	}

	@Nullable
	private static ImageIcon icon(@Nullable BufferedImage image, int size)
	{
		return image == null ? null : new ImageIcon(ImageUtil.resizeImage(image, size, size, true));
	}

	/** Label / value rows, with bold headers between groups (raids). */
	private static JPanel rows(List<Row> rows)
	{
		JPanel body = new JPanel(new GridBagLayout());
		body.setOpaque(false);
		GridBagConstraints c = new GridBagConstraints();
		c.gridy = 0;
		c.fill = GridBagConstraints.HORIZONTAL;
		for (Row row : rows)
		{
			c.insets = new Insets(row.header && c.gridy > 0 ? 8 : 1, 0, 1, 0);
			JLabel label = label(row.label, row.header ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR, SwingConstants.LEFT);
			JLabel value = label(row.value, row.header ? ColorScheme.LIGHT_GRAY_COLOR : row.valueColor, SwingConstants.RIGHT);
			if (row.header)
			{
				label.setFont(FontManager.getRunescapeBoldFont());
			}
			label.setToolTipText(row.tooltip);
			value.setToolTipText(row.tooltip);
			c.gridx = 0;
			c.weightx = 1;
			body.add(label, c);
			c.gridx = 1;
			c.weightx = 0;
			body.add(value, c);
			c.gridy++;
		}
		return body;
	}

	/** One line of a box: a label on the left and its value on the right. */
	private static final class Row
	{
		final String label;
		final String value;
		@Nullable
		final String tooltip;
		final boolean header;
		final Color valueColor;

		Row(String label, String value, @Nullable String tooltip, Color valueColor)
		{
			this(label, value, tooltip, false, valueColor);
		}

		private Row(String label, String value, @Nullable String tooltip, boolean header, Color valueColor)
		{
			this.label = label;
			this.value = value;
			this.tooltip = tooltip;
			this.header = header;
			this.valueColor = valueColor;
		}

		static Row header(String label, String value)
		{
			return new Row(label, value, null, true, Color.WHITE);
		}
	}

	/**
	 * A big value over a gray label. Centered tiles are the lifetime trio:
	 * an icon on top and the biggest values in the panel.
	 */
	private static final class Tile extends JPanel
	{
		private final JLabel icon = new JLabel();
		private final JLabel value = new JLabel();
		private final JLabel label = new JLabel();
		private final Font valueFont;

		Tile(Color background, boolean centered)
		{
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
			setBackground(background);
			setBorder(centered ? new EmptyBorder(8, 3, 7, 3) : new EmptyBorder(7, 7, 6, 4));
			float x = centered ? CENTER_ALIGNMENT : LEFT_ALIGNMENT;
			valueFont = centered ? TRIO_VALUE_FONT : TILE_VALUE_FONT;
			value.setFont(valueFont);
			value.setForeground(Color.WHITE);
			label.setFont(FontManager.getRunescapeFont());
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			icon.setAlignmentX(x);
			value.setAlignmentX(x);
			label.setAlignmentX(x);
			if (centered)
			{
				icon.setBorder(new EmptyBorder(0, 0, 4, 0));
				add(icon);
			}
			add(value);
			add(label);
		}

		Tile set(String valueText, String labelText, Color valueColor, @Nullable String tooltip)
		{
			value.setText(valueText);
			value.setForeground(valueColor);
			label.setText(labelText);
			setToolTipText(tooltip);
			value.setToolTipText(tooltip);
			label.setToolTipText(tooltip);
			return this;
		}

		void setIcon(@Nullable BufferedImage image)
		{
			icon.setIcon(ThrallPanel.icon(image, TRIO_ICON_SIZE));
			revalidate();
			repaint();
		}

		/**
		 * A top tile's value drops to the other tiles' size when it doesn't fit:
		 * a third of the panel is about 61 px with the scrollbar showing, and
		 * "387.9K" in the big font is 69 px, which Swing cut to "387....".
		 */
		@Override
		public void doLayout()
		{
			Insets insets = getInsets();
			int room = getWidth() - insets.left - insets.right;
			if (room > 0 && valueFont != TILE_VALUE_FONT)
			{
				boolean fits = getFontMetrics(valueFont).stringWidth(value.getText()) <= room;
				Font font = fits ? valueFont : TILE_VALUE_FONT;
				if (value.getFont() != font)
				{
					value.setFont(font);
				}
			}
			super.doLayout();
		}
	}

	/** A titled box whose title folds it away; the folded state is saved. */
	private final class FoldingBox extends JPanel
	{
		private final String id;
		private final JLabel arrow = new JLabel();
		private final JLabel info = new JLabel(INFO_ICON);
		private final JPanel body = new JPanel(new BorderLayout());

		FoldingBox(String id, String titleText)
		{
			this.id = id;
			setLayout(new BorderLayout(0, 4));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(new EmptyBorder(8, 8, 8, 8));

			JPanel titleBar = new JPanel(new BorderLayout(5, 0));
			titleBar.setOpaque(false);
			titleBar.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			titleBar.setToolTipText("Click to fold or unfold");
			arrow.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
			arrow.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			JLabel title = new JLabel(titleText);
			title.setFont(TITLE_FONT);
			title.setForeground(ACCENT);
			titleBar.add(arrow, BorderLayout.WEST);
			titleBar.add(title, BorderLayout.CENTER);
			info.setVisible(false);
			info.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					info.setIcon(INFO_ICON_HOVER);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					info.setIcon(INFO_ICON);
				}
			});
			titleBar.add(info, BorderLayout.EAST);
			titleBar.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (!folded.remove(id))
					{
						folded.add(id);
					}
					saveFolded();
					updateFold();
				}
			});

			body.setOpaque(false);
			add(titleBar, BorderLayout.NORTH);
			add(body, BorderLayout.CENTER);
			updateFold();
		}

		/** An ⓘ at the title's right that explains the box on hover. */
		void setInfo(String tooltip)
		{
			info.setToolTipText(tooltip);
			info.setVisible(true);
		}

		void setContent(JPanel content)
		{
			body.removeAll();
			body.add(content, BorderLayout.CENTER);
			body.revalidate();
			body.repaint();
		}

		private void updateFold()
		{
			boolean open = !folded.contains(id);
			arrow.setText(open ? "▼" : "▶");
			body.setVisible(open);
			ThrallPanel.this.revalidate();
			ThrallPanel.this.repaint();
		}
	}
}

package com.thrallinone;

import com.google.common.collect.ImmutableSet;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Projectile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tells other players' thrall projectiles from our thrall's, so they can be
 * hidden with their thralls. Thrall projectiles don't carry their source NPC
 * (as Pet Pathing and Combat found, and our own logs show), so each one is
 * judged once, when it is fired: a thrall projectile that doesn't start on our
 * thrall's tile is someone else's.
 */
@Slf4j
@Singleton
public class ThrallProjectiles
{
	/** Projectiles fired by ghostly and skeletal thralls, including the Leagues imp cosmetics. */
	private static final Set<Integer> THRALL_PROJECTILES = ImmutableSet.of(
		SpotanimID.THRALL_MAGIC_TRAVEL,
		SpotanimID.THRALL_RANGED_TRAVEL,
		SpotanimID.LEAGUES_6_THRALL_IMP_MAGIC_ATTACK_VFX_PROJANIM,
		SpotanimID.LEAGUES_6_THRALL_IMP_RANGED_ATTACK_VFX_PROJANIM);

	private final ThrallTracker tracker;

	/** Thrall projectiles already judged. */
	private final Set<Projectile> seen = Collections.newSetFromMap(new IdentityHashMap<>());
	/** The ones fired by other players' thralls. */
	private final Set<Projectile> others = Collections.newSetFromMap(new IdentityHashMap<>());

	@Inject
	ThrallProjectiles(ThrallTracker tracker)
	{
		this.tracker = tracker;
	}

	static boolean isThrallProjectile(int id)
	{
		return THRALL_PROJECTILES.contains(id);
	}

	/** The projectile was fired from the thrall's tile. */
	static boolean startsAt(Projectile projectile, NPC thrall)
	{
		LocalPoint location = thrall.getLocalLocation();
		return location != null
			&& Math.abs(projectile.getX1() - location.getX()) <= Perspective.LOCAL_TILE_SIZE / 2
			&& Math.abs(projectile.getY1() - location.getY()) <= Perspective.LOCAL_TILE_SIZE / 2;
	}

	/** Fired by another player's thrall. Read for every drawn projectile, so a set lookup only. */
	boolean isOthers(Projectile projectile)
	{
		return others.contains(projectile);
	}

	void reset()
	{
		seen.clear();
		others.clear();
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		Projectile projectile = event.getProjectile();
		if (!isThrallProjectile(projectile.getId()) || !seen.add(projectile))
		{
			return;
		}
		NPC owned = tracker.getOwned();
		if (owned == null || !startsAt(projectile, owned))
		{
			others.add(projectile);
			// With no thrall claimed, a projectile from ours would wrongly count as someone else's.
			log.debug("Thrall projectile {} judged someone else's ({})", projectile.getId(),
				owned == null ? "no thrall claimed" : "not from our thrall's tile");
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		seen.removeIf(projectile -> projectile.getRemainingCycles() <= 0);
		others.retainAll(seen);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
			case LOADING:
				reset();
				break;
			default:
				break;
		}
	}
}

package com.thrallinone;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Data;

/**
 * Lifetime thrall records for one account, saved as JSON in the RuneLite
 * profile: totals over every saved fight, the same per raid, and summons,
 * prayer and rune cost, added as each thrall is cast.
 */
@Data
class ThrallRecords
{
	private int version = 2;

	private FightTotals lifetime = new FightTotals();
	private Map<ThrallType, Long> damageByType = new LinkedHashMap<>();
	/** Per raid, keyed by {@link BossKey}'s raid name. */
	private Map<String, BossRecord> bosses = new LinkedHashMap<>();

	private int summons;
	private Map<ThrallType, Integer> summonsByType = new LinkedHashMap<>();
	private long prayerSpent;
	/** What the runes that left the inventory or rune pouch on our casts were worth on the day. */
	private long gpSpent;

	@Data
	static class BossRecord
	{
		private FightTotals totals = new FightTotals();
	}

	void addFight(FightRecord fight)
	{
		lifetime.add(fight);
		fight.getDamageByType().forEach((type, damage) -> damageByType.merge(type, (long) damage, Long::sum));
		if (BossKey.isRaid(fight.getBoss()))
		{
			bosses.computeIfAbsent(fight.getBoss(), name -> new BossRecord()).totals.add(fight);
		}
	}

	/**
	 * One cast of ours. The type and tier are null when the thrall it raised
	 * wasn't seen; then only the count and cost go up.
	 */
	void addSummon(ThrallType type, ThrallTier tier, long gp)
	{
		summons++;
		if (type != null)
		{
			summonsByType.merge(type, 1, Integer::sum);
		}
		if (tier != null)
		{
			prayerSpent += tier.getPrayerCost();
		}
		gpSpent += gp;
	}

	/** Fill in anything a damaged save left out, and drop entries that aren't raids. */
	ThrallRecords repair()
	{
		if (lifetime == null)
		{
			lifetime = new FightTotals();
		}
		if (damageByType == null)
		{
			damageByType = new LinkedHashMap<>();
		}
		if (bosses == null)
		{
			bosses = new LinkedHashMap<>();
		}
		bosses.entrySet().removeIf(boss -> boss.getValue() == null || boss.getValue().totals == null
			|| !BossKey.isRaid(boss.getKey()));
		if (summonsByType == null)
		{
			summonsByType = new LinkedHashMap<>();
		}
		// An enum name that doesn't exist reads back as a null key.
		damageByType.remove(null);
		summonsByType.remove(null);
		version = 2;
		return this;
	}
}

package com.thrallinone;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * "Recast Thrall" and the can't-summon warnings, above the chatbox. Each line
 * is its own filled box, like All-in-One Reminders' banner: the recast
 * box in the configured color, steady or pulsing, and the warnings in amber.
 * A preview of the recast box follows the Steady/Pulsing choice even while
 * the box is off.
 */
class ThrallReminderOverlay extends Overlay
{
	private static final String RECAST_TEXT = "Recast Thrall";
	private static final Color WARNING_FILL = new Color(168, 104, 18);

	private static final int PAD_X = 8;
	private static final int PAD_Y = 3;
	private static final int GAP = 3;
	/** One pulse every 1.4 s, dimming the fill to 72% at its lowest. */
	private static final long PULSE_MILLIS = 1400;
	private static final double PULSE_DEPTH = 0.28;

	private final ThrallReminders reminders;
	private final ThrallInOneConfig config;
	private final List<String> lines = new ArrayList<>(3);

	@Inject
	ThrallReminderOverlay(ThrallReminders reminders, ThrallInOneConfig config)
	{
		this.reminders = reminders;
		this.config = config;
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean recast = reminders.showExpired();

		lines.clear();
		if (recast)
		{
			lines.add(RECAST_TEXT);
		}
		if (reminders.showWrongSpellbook())
		{
			lines.add("Not on the Arceuus Spellbook");
		}
		if (reminders.showMissingBook())
		{
			lines.add("No Book of the Dead");
		}
		if (lines.isEmpty())
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics metrics = graphics.getFontMetrics();
		int width = 0;
		for (String line : lines)
		{
			width = Math.max(width, metrics.stringWidth(line));
		}
		width += 2 * PAD_X;
		int height = metrics.getHeight() + 2 * PAD_Y;

		Color recastFill = config.expiredBoxColor();
		boolean pulse = config.recastBox() == RecastBox.PULSING;
		int y = 0;
		for (int i = 0; i < lines.size(); i++)
		{
			String line = lines.get(i);
			boolean isRecast = recast && i == 0;
			Color fill = isRecast ? recastFill : WARNING_FILL;

			graphics.setColor(isRecast && pulse ? pulse(fill) : fill);
			graphics.fillRect(0, y, width, height);
			graphics.setColor(fill.darker());
			graphics.drawRect(0, y, width - 1, height - 1);

			int textX = (width - metrics.stringWidth(line)) / 2;
			int textY = y + PAD_Y + metrics.getAscent();
			graphics.setColor(Color.BLACK);
			graphics.drawString(line, textX + 1, textY + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(line, textX, textY);

			y += height + GAP;
		}
		return new Dimension(width, y - GAP);
	}

	private static Color pulse(Color color)
	{
		double phase = (System.currentTimeMillis() % PULSE_MILLIS) / (double) PULSE_MILLIS;
		double scale = 1 - PULSE_DEPTH * (1 - Math.cos(2 * Math.PI * phase)) / 2;
		return new Color(
			(int) (color.getRed() * scale),
			(int) (color.getGreen() * scale),
			(int) (color.getBlue() * scale),
			color.getAlpha());
	}
}

package com.thrallinone;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.eventbus.Subscribe;

/**
 * Reminders: our thrall ran out and we're fighting without one, and
 * (optional) we couldn't summon another because we're on the wrong spellbook
 * or don't have the Book of the Dead; those two show only in fights within
 * 10 minutes of having a thrall out. We count as fighting for the configured
 * timeout after any hitsplat on us or by us, and while we're attacking an NPC
 * with a combat level; dying or leaving a raid ends the fight. The expiry notification fires once per expiry: when
 * the thrall runs out mid-fight, or when we next start fighting without one.
 * A thrall left behind in another instance ({@link ThrallTracker#isLeftBehind})
 * counts as expired, though the varbit stays on. None of these show where a thrall can't be summoned ({@link NoSummonTracker});
 * an expiry notification held back there fires once we fight somewhere else.
 * These only show information; nothing is cast for you.
 */
@Slf4j
@Singleton
public class ThrallReminders
{
	/** The can't-summon warnings show in fights up to this long after our last thrall (10 minutes). */
	private static final int RECENT_USE_TICKS = 1000;
	/** {@link VarbitID#SPELLBOOK} on the Arceuus spellbook (no gameval names its values). */
	static final int ARCEUUS_SPELLBOOK = 3;
	/** How long a preview from the sidebar shows. */
	static final long PREVIEW_MILLIS = 10_000;
	/** Hits landing this soon after we die don't start a new fight. */
	private static final int DEATH_GRACE_TICKS = 3;

	private final Client client;
	private final ThrallTracker tracker;
	private final ThrallInOneConfig config;
	private final Notifier notifier;
	private final NoSummonTracker noSummon;

	/** The resurrection varbit; {@link #thrallOut()} also allows for a thrall left behind. */
	private boolean active;
	/** The tracker's last left-behind tick already counted as an expiry. */
	private int leftBehindSeen = -1;
	private boolean expiryCheckPending;
	private int lastCombatTick = -1;
	private int expiredTick = -1;
	private boolean expiryNotified;
	private int lastThrallTick = -1;
	private int diedTick = -1;
	/** The raid we stood in last tick, or null. */
	@Nullable
	private String raid;

	private boolean wrongSpellbook;
	private boolean missingBook;

	/** The reminder a sidebar preview button is showing, until {@link #previewUntil}. */
	@Nullable
	private volatile PreviewReminder preview;
	private volatile long previewUntil;

	@Inject
	ThrallReminders(Client client, ThrallTracker tracker, ThrallInOneConfig config, Notifier notifier,
		NoSummonTracker noSummon)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.notifier = notifier;
		this.noSummon = noSummon;
	}

	void reset()
	{
		active = client.getVarbitValue(VarbitID.ARCEUUS_RESURRECTION_ACTIVE) != 0;
		leftBehindSeen = -1;
		expiryCheckPending = false;
		lastCombatTick = -1;
		expiredTick = -1;
		expiryNotified = false;
		lastThrallTick = active ? client.getTickCount() : -1;
		diedTick = -1;
		raid = null;
		wrongSpellbook = false;
		missingBook = false;
	}

	public boolean isInCombat()
	{
		return lastCombatTick >= 0 && client.getTickCount() - lastCombatTick <= Fight.secondsToTicks(config.combatTimeoutSeconds());
	}

	/** Our thrall ran out during a fight and we haven't summoned another yet (or it's being previewed). */
	public boolean showExpired()
	{
		return previewing(PreviewReminder.RECAST)
			|| config.remindersEnabled() && config.recastBox() != RecastBox.OFF
				&& expiredTick >= 0 && !thrallOut() && isInCombat() && canSummonHere();
	}

	/**
	 * Our thrall is out: the varbit is on and we didn't leave it behind in
	 * another instance, where the varbit can stay on long after it's gone.
	 */
	private boolean thrallOut()
	{
		return active && !tracker.isLeftBehind();
	}

	public boolean showWrongSpellbook()
	{
		return previewing(PreviewReminder.SPELLBOOK)
			|| config.remindersEnabled() && config.summonCheck() && wrongSpellbook && warningApplies();
	}

	public boolean showMissingBook()
	{
		return previewing(PreviewReminder.BOOK)
			|| config.remindersEnabled() && config.bookWarning() && missingBook && warningApplies();
	}

	/**
	 * Show a reminder for {@link #PREVIEW_MILLIS}, ignoring the reminder
	 * settings; the recast box (and All) also sends the expiry notification.
	 * Client thread.
	 */
	void preview(PreviewReminder reminder)
	{
		preview = reminder;
		previewUntil = System.currentTimeMillis() + PREVIEW_MILLIS;
		if (reminder.shows(PreviewReminder.RECAST))
		{
			notifier.notify(config.expiryNotification(), "Your thrall has expired");
		}
	}

	private boolean previewing(PreviewReminder reminder)
	{
		PreviewReminder shown = preview;
		return shown != null && shown.shows(reminder) && System.currentTimeMillis() < previewUntil;
	}

	/**
	 * Warn that we can't summon a thrall only while it would matter: no
	 * thrall out, fighting, and using thralls lately. A player who doesn't
	 * use thralls never sees these, and after a trip they stay quiet at the
	 * bank.
	 */
	private boolean warningApplies()
	{
		if (thrallOut() || !canSummonHere() || !isInCombat())
		{
			return false;
		}
		int sinceThrall = client.getTickCount() - lastThrallTick;
		// Negative if the tick count started again (a relog): not recent then.
		return lastThrallTick >= 0 && sinceThrall >= 0 && sinceThrall <= RECENT_USE_TICKS;
	}

	/** False where thralls can't be summoned (and the setting to stay quiet there is on). */
	private boolean canSummonHere()
	{
		return !config.quietWhereNoSummon() || !noSummon.isNoSummonHere();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player me = client.getLocalPlayer();
		int tick = client.getTickCount();
		if ((event.getActor() == me || event.getHitsplat().isMine()) && !justDied(tick))
		{
			lastCombatTick = tick;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			diedTick = client.getTickCount();
			lastCombatTick = -1;
			log.debug("We died at tick {}; no longer in combat", diedTick);
		}
	}

	/** Hits still landing just after we died don't start a new fight. */
	private boolean justDied(int tick)
	{
		return diedTick >= 0 && tick >= diedTick && tick - diedTick <= DEATH_GRACE_TICKS;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.ARCEUUS_RESURRECTION_ACTIVE)
		{
			return;
		}

		boolean nowActive = event.getValue() != 0;
		if (nowActive == active)
		{
			return;
		}
		active = nowActive;
		lastThrallTick = client.getTickCount();
		if (active)
		{
			expiredTick = -1;
		}
		else
		{
			// Decide at the end of the tick, once a recast in the same tick
			// (which also clears the varbit) has shown its cast graphic.
			expiryCheckPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		if (expiryCheckPending)
		{
			expiryCheckPending = false;
			boolean recast = tracker.getLastCastTick() >= 0 && tick - tracker.getLastCastTick() <= 1;
			// Already counted as expired when it was left behind: one notification per thrall.
			if (!active && !recast && expiredTick < 0)
			{
				expiredTick = tick;
				expiryNotified = false;
				log.debug("Thrall expired at tick {} (in combat: {}, last combat tick {}, cooldown varbit {})",
					tick, isInCombat(), lastCombatTick, client.getVarbitValue(VarbitID.ARCEUUS_RESURRECTION_COOLDOWN));
			}
		}

		// Left behind in another instance: as good as expired, though the varbit stays on.
		int leftBehind = tracker.getLeftBehindTick();
		if (leftBehind >= 0 && leftBehind != leftBehindSeen)
		{
			leftBehindSeen = leftBehind;
			// Recent use for the warnings: the varbit may not change again for a long while.
			lastThrallTick = leftBehind;
			if (expiredTick < 0)
			{
				expiredTick = leftBehind;
				expiryNotified = false;
				log.debug("Thrall left behind at tick {}: counts as expired (in combat: {}, last combat tick {})",
					leftBehind, isInCombat(), lastCombatTick);
			}
		}

		// Recast since the expiry: our cast graphic shows at once, the varbit
		// only about 5 ticks later, so don't wait for it to clear the reminder.
		if (expiredTick >= 0 && tracker.getLastCastTick() >= expiredTick)
		{
			log.debug("Recast at tick {} after the expiry at tick {}", tracker.getLastCastTick(), expiredTick);
			expiredTick = -1;
		}

		// Teleporting out of a raid (or a wipe) ends the fight: a thrall left
		// behind there would otherwise bring up the reminder outside.
		String raidNow = BossKey.current(client);
		if (raid != null && !raid.equals(raidNow) && lastCombatTick >= 0)
		{
			lastCombatTick = -1;
			log.debug("Left {} at tick {}; no longer in combat", raid, tick);
		}
		raid = raidNow;

		Player me = client.getLocalPlayer();
		Actor target = me == null ? null : me.getInteracting();
		if (target instanceof NPC && ((NPC) target).getCombatLevel() > 0 && !justDied(tick))
		{
			lastCombatTick = tick;
		}

		// Once per expiry, as soon as we're fighting without a thrall somewhere we could summon one.
		// With reminders off it still counts as sent, so turning them back on mid-fight doesn't fire a stale one.
		if (expiredTick >= 0 && !thrallOut() && !expiryNotified && isInCombat() && canSummonHere())
		{
			expiryNotified = true;
			if (config.remindersEnabled())
			{
				log.debug("Expiry notification at tick {}, {} ticks after the expiry", tick, tick - expiredTick);
				notifier.notify(config.expiryNotification(), "Your thrall has expired");
			}
		}

		wrongSpellbook = config.summonCheck() && client.getVarbitValue(VarbitID.SPELLBOOK) != ARCEUUS_SPELLBOOK;
		missingBook = config.bookWarning() && !contains(InventoryID.WORN) && !contains(InventoryID.INV);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
				active = false;
				expiryCheckPending = false;
				expiredTick = -1;
				lastCombatTick = -1;
				break;
			default:
				break;
		}
	}

	private boolean contains(int inventoryId)
	{
		ItemContainer container = client.getItemContainer(inventoryId);
		return container != null && container.contains(ItemID.BOOK_OF_THE_DEAD);
	}
}

package com.thrallinone;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.NPC;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.AreaSoundEffectPlayed;
import net.runelite.api.events.SoundEffectPlayed;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;

/**
 * Silences thralls' sounds. The game sends every sound without its source
 * actor, so thrall sounds are known by id (names from the wiki's List of
 * sound IDs; there are no gameval constants for sounds). Attacks are area
 * sounds played on the attacking thrall's tile, which tells ours from other
 * players'. The Resurrect spells' sounds are plain sounds played to the caster
 * alone. The Deadman thralls (Zuk, Kalphite Princess and Wisp) have no sounds
 * of their own in the game's data, so they are covered by the standard ones.
 */
@Singleton
public class ThrallSounds
{
	/**
	 * Attack sounds that other things share, so muted only on a thrall's tile:
	 * ghostly "waterstrike_cast_and_fire", skeletal "longbow", zombified "zombie_attack".
	 * The imps play them too.
	 */
	static final Set<Integer> SHARED_ATTACK_SOUNDS = ImmutableSet.of(211, 2700, 918);
	/**
	 * The Leagues imp thralls' attack sounds ("l6_imp_magic_attack_*", "l6_imp_melee_attack_*",
	 * "l6_imp_ranged_attack_*"), used by nothing else. The magic projectile's sounds may play
	 * along its flight rather than on the imp.
	 */
	static final Set<Integer> IMP_ATTACK_SOUNDS = ImmutableSet.<Integer>builder()
		.addAll(range(11375, 11382))
		.add(11398, 11399)
		.build();
	/**
	 * Raising and losing a thrall: the Resurrect spells' "cast_and_fire" sounds (lesser, superior and
	 * greater ghost, skeleton and zombie), "resurrect_end" (expiry, or a recast over it), and the
	 * Leagues imps' spawn, transition and despawn sounds.
	 */
	static final Set<Integer> SUMMON_SOUNDS = ImmutableSet.<Integer>builder()
		.add(5061, 5028, 5063)
		.add(5025, 5039, 5048)
		.add(5040, 5057, 5058)
		.add(5054)
		.addAll(range(11370, 11374))
		.addAll(range(11383, 11397))
		.build();
	/** A sound this many tiles from a thrall is that thrall's. */
	private static final int SOUND_TILES = 1;
	/** An imp's projectile sound can play this far from the imp that fired it. */
	private static final int PROJECTILE_TILES = 10;

	private static final Predicate<NPC> ANY_THRALL = npc -> true;
	private static final Predicate<NPC> IMP = npc -> ThrallNpcs.isImp(npc.getId());

	private final ThrallInOneConfig config;
	private final ThrallTracker tracker;

	// Read for every sound the game plays, so cached instead of going through
	// the config proxy; written when settings change.
	private volatile MuteThralls muteAttacks = MuteThralls.OFF;
	private volatile boolean muteSummons;

	@Inject
	ThrallSounds(ThrallInOneConfig config, ThrallTracker tracker)
	{
		this.config = config;
		this.tracker = tracker;
	}

	private static Set<Integer> range(int first, int last)
	{
		return IntStream.rangeClosed(first, last).boxed().collect(Collectors.toSet());
	}

	/** Read the mute settings. */
	void reset()
	{
		muteAttacks = config.muteThralls();
		muteSummons = config.muteSummonSounds();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ThrallInOneConfig.GROUP.equals(event.getGroup()))
		{
			reset();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		reset();
	}

	@Subscribe
	public void onAreaSoundEffectPlayed(AreaSoundEffectPlayed event)
	{
		MuteThralls attacks = muteAttacks;
		if (attacks == MuteThralls.OFF && !muteSummons)
		{
			return;
		}

		int id = event.getSoundId();
		if (SUMMON_SOUNDS.contains(id))
		{
			if (muteSummons)
			{
				event.consume();
			}
			return;
		}
		if (attacks == MuteThralls.OFF)
		{
			return;
		}

		int x = event.getSceneX();
		int y = event.getSceneY();
		if (SHARED_ATTACK_SOUNDS.contains(id))
		{
			NPC thrall = thrallNear(x, y, SOUND_TILES, ANY_THRALL);
			if (thrall != null && attacks.mutes(tracker.isOwned(thrall)))
			{
				event.consume();
			}
		}
		else if (IMP_ATTACK_SOUNDS.contains(id))
		{
			// Only an imp makes these, so a ghost standing closer isn't the one that played it.
			NPC imp = thrallNear(x, y, PROJECTILE_TILES, IMP);
			if (imp != null ? attacks.mutes(tracker.isOwned(imp)) : attacks == MuteThralls.ALL)
			{
				event.consume();
			}
		}
	}

	@Subscribe
	public void onSoundEffectPlayed(SoundEffectPlayed event)
	{
		MuteThralls attacks = muteAttacks;
		if (attacks == MuteThralls.OFF && !muteSummons)
		{
			return;
		}

		int id = event.getSoundId();
		if (SUMMON_SOUNDS.contains(id))
		{
			if (muteSummons)
			{
				event.consume();
			}
		}
		// A plain sound is played to us alone, so the imp is ours.
		else if (IMP_ATTACK_SOUNDS.contains(id) && attacks.mutes(true))
		{
			event.consume();
		}
	}

	/** The thrall matching the filter nearest a sound's tile, within the given tiles. */
	@Nullable
	private NPC thrallNear(int sceneX, int sceneY, int tiles, Predicate<NPC> filter)
	{
		NPC nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (NPC thrall : tracker.getThralls())
		{
			LocalPoint location = thrall.getLocalLocation();
			if (location == null || !filter.test(thrall))
			{
				continue;
			}
			int distance = Math.max(Math.abs(location.getSceneX() - sceneX), Math.abs(location.getSceneY() - sceneY));
			if (distance <= tiles && distance < nearestDistance)
			{
				nearest = thrall;
				nearestDistance = distance;
			}
		}
		return nearest;
	}
}

package com.thrallinone;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Loads and saves {@link ThrallRecords} for the logged-in account, as JSON
 * under an rsprofile key, so each account keeps its own records.
 */
@Slf4j
@Singleton
class ThrallStatsStore
{
	static final String RECORDS_KEY = "records";

	private final ConfigManager configManager;
	/** The injected Gson with enum map keys (see {@link #withEnumKeys}), built once. */
	private final Gson gson;

	@Getter
	private ThrallRecords records = new ThrallRecords();
	/** The account the records belong to; null while logged out or while its save is unreadable. */
	@Nullable
	private String profileKey;
	/** The account whose save couldn't be read: left alone, unless the player resets their records. */
	@Nullable
	private String unreadableKey;

	@Inject
	ThrallStatsStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = withEnumKeys(gson);
	}

	/** Load the current account's records (empty while logged out). */
	void load()
	{
		profileKey = configManager.getRSProfileKey();
		unreadableKey = null;
		String json = profileKey == null ? null : configManager.getRSProfileConfiguration(ThrallInOneConfig.GROUP, RECORDS_KEY);
		ThrallRecords loaded = read(gson, json);
		if (loaded == null)
		{
			// Keep the unreadable save rather than overwrite it with empty records.
			log.warn("Couldn't read the saved thrall records; they won't be updated until they're reset");
			unreadableKey = profileKey;
			profileKey = null;
			loaded = new ThrallRecords();
		}
		records = loaded;
		log.debug("Loaded thrall records for profile {}: {} fights, {} summons",
			profileKey, records.getLifetime().getFights(), records.getSummons());
	}

	void save()
	{
		// Never write one account's records under another's key.
		if (profileKey == null || !profileKey.equals(configManager.getRSProfileKey()))
		{
			return;
		}
		configManager.setRSProfileConfiguration(ThrallInOneConfig.GROUP, RECORDS_KEY, gson.toJson(records));
	}

	/** Clear the account's records, including a save that couldn't be read; saving works again afterwards. */
	void reset()
	{
		records = new ThrallRecords();
		String current = configManager.getRSProfileKey();
		if (unreadableKey != null && unreadableKey.equals(current))
		{
			profileKey = unreadableKey;
			unreadableKey = null;
		}
		if (profileKey != null && profileKey.equals(current))
		{
			configManager.unsetRSProfileConfiguration(ThrallInOneConfig.GROUP, RECORDS_KEY);
		}
	}

	/** A copy for another thread (the sidebar panel) to read. */
	ThrallRecords copy()
	{
		return read(gson, gson.toJson(records));
	}

	static String toJson(Gson gson, ThrallRecords records)
	{
		return withEnumKeys(gson).toJson(records);
	}

	/**
	 * Gson writes plain map keys with toString() but reads enum keys by name,
	 * so a map keyed by an enum with a display toString (ThrallTier) wouldn't
	 * read back. Complex map key serialization writes keys through their type
	 * adapter, i.e. by name, the same JSON as before for every other key.
	 */
	private static Gson withEnumKeys(Gson gson)
	{
		return gson.newBuilder().enableComplexMapKeySerialization().create();
	}

	/** Records from JSON: empty for no save, null if the save can't be read. */
	@Nullable
	static ThrallRecords fromJson(Gson gson, @Nullable String json)
	{
		return read(withEnumKeys(gson), json);
	}

	@Nullable
	private static ThrallRecords read(Gson recordsGson, @Nullable String json)
	{
		if (json == null || json.isEmpty())
		{
			return new ThrallRecords();
		}
		try
		{
			ThrallRecords records = recordsGson.fromJson(json, ThrallRecords.class);
			return records == null ? new ThrallRecords() : records.repair();
		}
		catch (JsonParseException | IllegalStateException e)
		{
			log.debug("Unreadable thrall records", e);
			return null;
		}
	}
}

package com.thrallinone;

import java.util.Collections;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.game.ItemManager;

/**
 * Counts our casts and adds each summon to the saved records: which thrall it
 * raised, its prayer, and what it cost. Driven once a tick by
 * {@link ThrallFights}, which owns the records and the panel updates.
 *
 * <p>The runes that leave the inventory or rune pouch between the tick before
 * the cast and the tick after it are measured (staves, tomes and combination
 * runes change them) only to price the cast; the records keep the cost, not
 * the runes.
 */
@Slf4j
@Singleton
class ThrallSummons
{
	/** Give up working out which thrall a cast raised after this many ticks. */
	private static final int SUMMON_RESOLVE_TICKS = 10;

	private final Client client;
	private final ThrallTracker tracker;
	private final ThrallStatsStore store;
	private final ItemManager itemManager;

	/** Casts this login session. */
	@Getter
	private int sessionCasts;
	private int lastSeenCastTick = -1;
	@Nullable
	private PendingSummon pending;
	@Nullable
	private NPC ownedLastTick;
	private Map<Integer, Integer> runesLastTick = Collections.emptyMap();

	@Inject
	ThrallSummons(Client client, ThrallTracker tracker, ThrallStatsStore store, ItemManager itemManager)
	{
		this.client = client;
		this.tracker = tracker;
		this.store = store;
		this.itemManager = itemManager;
	}

	void reset()
	{
		sessionCasts = 0;
		lastSeenCastTick = tracker.getLastCastTick();
		pending = null;
		ownedLastTick = tracker.getOwned();
		runesLastTick = Collections.emptyMap();
	}

	/** Logged out or hopped: the tick count can start again after this. */
	void loggedOut(boolean newSession)
	{
		pending = null;
		lastSeenCastTick = -1;
		if (newSession)
		{
			sessionCasts = 0;
		}
	}

	/**
	 * Once a game tick. Returns what changed: {@link Change#CAST} when a new
	 * cast was counted, {@link Change#SUMMON} when a summon was added to the
	 * records (and saved).
	 */
	Change tick(int tick)
	{
		Map<Integer, Integer> runes = RuneCounts.read(client);
		boolean cast = noteCast(tick);
		boolean summoned = resolveSummon(tick, runes);
		runesLastTick = runes;
		ownedLastTick = tracker.getOwned();
		return summoned ? Change.SUMMON : cast ? Change.CAST : Change.NONE;
	}

	enum Change
	{
		NONE,
		CAST,
		SUMMON,
	}

	/** Notice a new cast of ours from the tracker's cast graphic (which reports each cast once). */
	private boolean noteCast(int tick)
	{
		int castTick = tracker.getLastCastTick();
		if (castTick < 0 || castTick == lastSeenCastTick)
		{
			return false;
		}
		lastSeenCastTick = castTick;
		sessionCasts++;
		pending = new PendingSummon(castTick, runesLastTick, ownedLastTick);
		log.debug("Thrall cast at tick {} (seen at tick {})", castTick, tick);
		return true;
	}

	/** Once the cast's thrall is known and the runes have had a tick to leave the inventory, add the summon to the records. */
	private boolean resolveSummon(int tick, Map<Integer, Integer> runes)
	{
		if (pending == null)
		{
			return false;
		}
		if (tick == pending.castTick + 1)
		{
			pending.after = runes;
		}

		NPC owned = tracker.getOwned();
		boolean raised = owned != null && owned != pending.ownedBefore;
		if (pending.after == null || !raised && tick - pending.castTick < SUMMON_RESOLVE_TICKS)
		{
			return false;
		}

		ThrallType type = raised ? ThrallType.of(owned.getId()) : null;
		ThrallTier tier = raised ? ThrallTier.of(owned.getId()) : null;
		Map<Integer, Integer> used = tier == null
			? Collections.emptyMap()
			: RuneCounts.usedByCast(tier, pending.before, pending.after);
		long gp = 0;
		for (Map.Entry<Integer, Integer> rune : used.entrySet())
		{
			gp += (long) itemManager.getItemPrice(rune.getKey()) * rune.getValue();
		}
		log.debug("Summon at tick {}: {} {}, runes {}, {} gp", pending.castTick, tier, type, used, gp);
		pending = null;

		store.getRecords().addSummon(type, tier, gp);
		store.save();
		return true;
	}

	private static final class PendingSummon
	{
		final int castTick;
		final Map<Integer, Integer> before;
		@Nullable
		final NPC ownedBefore;
		@Nullable
		Map<Integer, Integer> after;

		PendingSummon(int castTick, Map<Integer, Integer> before, @Nullable NPC ownedBefore)
		{
			this.castTick = castTick;
			this.before = before;
			this.ownedBefore = ownedBefore;
		}
	}
}

package com.thrallinone;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * The three thrall tiers: the runes and prayer one Resurrect spell of that
 * tier costs, and how hard the thrall hits. Ghostly, skeletal and zombified
 * thralls of a tier cost the same.
 *
 * <p>Source: OSRS wiki, "Thrall" (https://oldschool.runescape.wiki/w/Thrall):
 * <ul>
 * <li>Resurrect Lesser Ghost / Skeleton / Zombie: level 38, 10 air, 1 cosmic, 5 mind.</li>
 * <li>Resurrect Superior Ghost / Skeleton / Zombie: level 57, 10 earth, 1 cosmic, 5 death.</li>
 * <li>Resurrect Greater Ghost / Skeleton / Zombie: level 76, 10 fire, 1 cosmic, 5 blood.</li>
 * </ul>
 * Every cast also needs the Book of the Dead, worn or in the inventory, and
 * costs prayer points. A thrall hits 0 to its max every 4 ticks without
 * missing, so its expected DPS is the average hit over 2.4 seconds.
 */
@Getter
public enum ThrallTier
{
	LESSER("Lesser", ImmutableMap.of(Rune.AIR, 10, Rune.COSMIC, 1, Rune.MIND, 5), 1, 2),
	SUPERIOR("Superior", ImmutableMap.of(Rune.EARTH, 10, Rune.COSMIC, 1, Rune.DEATH, 5), 2, 4),
	GREATER("Greater", ImmutableMap.of(Rune.FIRE, 10, Rune.COSMIC, 1, Rune.BLOOD, 5), 3, 6);

	private static final double ATTACK_SECONDS = 2.4;

	private final String displayName;
	/** Runes one cast uses. */
	private final Map<Rune, Integer> runes;
	private final int maxHit;
	private final int prayerCost;

	ThrallTier(String displayName, Map<Rune, Integer> runes, int maxHit, int prayerCost)
	{
		this.displayName = displayName;
		this.runes = runes;
		this.maxHit = maxHit;
		this.prayerCost = prayerCost;
	}

	/** Average damage per second: thralls always hit, uniformly 0 to the max. */
	public double getExpectedDps()
	{
		return maxHit / 2.0 / ATTACK_SECONDS;
	}

	/** The tier of a thrall NPC ({@link ThrallNpcs}), or null for any other NPC. */
	@Nullable
	public static ThrallTier of(int npcId)
	{
		return ThrallNpcs.tier(npcId);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.thrallinone;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;

/**
 * Time left on our thrall. A thrall lasts one tick per boosted Magic level,
 * twice that once the Master combat achievement rewards are claimed (OSRS
 * wiki, "Thrall"). Measured in game, the resurrection varbit turns on about
 * five ticks after the cast and clears one tick short of the level in ticks
 * later. The countdown runs from the spawn when the tracker claimed the
 * thrall from our cast, then from the varbit, which lands on the same expiry.
 * The varbit clearing ends it exactly, whatever the estimate said.
 *
 * <p>When the plugin starts with a thrall already out, the varbit change was
 * missed. So each countdown is saved to the RuneLite profile as its expiry on
 * the map clock (a server tick counter, varp 3079) plus the thrall's NPC
 * index, and resumes if a thrall with that index is still out. (The buff
 * bar's client vars for the thrall, varc 524 and 1147, looked like a source
 * but stayed 0 in game even with the buff bar and its thrall timer on.)
 */
@Slf4j
@Singleton
public class ThrallTimer
{
	private static final int CA_TIER_CLAIMED = 2;
	private static final String SAVED_END_KEY = "thrallEnd";
	/** Longer than any thrall can last: twice a boosted 99 Magic, with room to spare. */
	private static final int MAX_TICKS = 250;
	/** Measured in game: the varbit turns on this many ticks after our thrall spawns. */
	private static final int SPAWN_TO_VARBIT_TICKS = 5;

	private final Client client;
	private final ThrallTracker tracker;
	private final ConfigManager configManager;

	private boolean active;
	private int activeTick = -1;
	private int endTick = -1;

	@Inject
	ThrallTimer(Client client, ThrallTracker tracker, ConfigManager configManager)
	{
		this.client = client;
		this.tracker = tracker;
		this.configManager = configManager;
	}

	void reset()
	{
		active = client.getVarbitValue(VarbitID.ARCEUUS_RESURRECTION_ACTIVE) != 0;
		activeTick = -1;
		endTick = -1;
		if (!active)
		{
			return;
		}

		// Started part way through a thrall.
		int remaining = remainingFromSaved();
		if (remaining >= 0)
		{
			endTick = client.getTickCount() + remaining;
		}
		log.debug("Thrall out at start-up: {} ticks left from the saved expiry (saved {}, map clock {})",
			remaining, savedEnd(), mapClock());
	}

	/** Ticks left from the saved expiry, or -1 unless the thrall it was saved for is still out. */
	private int remainingFromSaved()
	{
		String saved = savedEnd();
		if (saved == null)
		{
			return -1;
		}

		int endMapClock;
		int npcIndex;
		try
		{
			String[] parts = saved.split(":");
			endMapClock = Integer.parseInt(parts[0]);
			npcIndex = Integer.parseInt(parts[1]);
		}
		catch (RuntimeException e)
		{
			return -1;
		}

		WorldView wv = client.getTopLevelWorldView();
		NPC npc = wv == null ? null : wv.npcs().byIndex(npcIndex);
		if (npc == null || !ThrallType.isThrall(npc.getId()))
		{
			// A different thrall, cast while the plugin was off.
			return -1;
		}
		return remainingUntil(endMapClock, mapClock());
	}

	/** Ticks from now to an expiry on the map clock, or -1 when it isn't a plausible thrall expiry. */
	static int remainingUntil(int endMapClock, int mapClock)
	{
		int remaining = endMapClock - mapClock;
		return remaining > 0 && remaining <= MAX_TICKS ? remaining : -1;
	}

	private String savedEnd()
	{
		return configManager.getRSProfileConfiguration(ThrallInOneConfig.GROUP, SAVED_END_KEY);
	}

	private int mapClock()
	{
		return client.getVarpValue(VarPlayerID.MAP_CLOCK);
	}

	/** Ticks until our thrall expires, or -1 when there is no thrall, it was left behind, or its start was missed. */
	public int getRemainingTicks()
	{
		if (tracker.isLeftBehind())
		{
			// The varbit may stay on long after (see ThrallLoss); nothing of ours is counting down.
			return -1;
		}
		int end = endTick;
		// Claimed from our cast on the spawn tick, before the varbit (or with
		// the varbit still on from the thrall it replaced): count from the spawn.
		int spawnTick = tracker.getOwnedSpawnTick();
		if (spawnTick >= 0 && spawnTick > activeTick)
		{
			end = spawnTick + SPAWN_TO_VARBIT_TICKS + durationTicks() - 1;
		}
		if (end < 0)
		{
			return -1;
		}
		return Math.max(0, end - client.getTickCount());
	}

	/** How long a thrall cast now lasts, in ticks after the varbit turns on, plus one. */
	private int durationTicks()
	{
		boolean doubled = client.getVarbitValue(VarbitID.CA_TIER_STATUS_MASTER) == CA_TIER_CLAIMED;
		return client.getBoostedSkillLevel(Skill.MAGIC) * (doubled ? 2 : 1);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.ARCEUUS_RESURRECTION_ACTIVE)
		{
			return;
		}

		boolean nowActive = event.getValue() != 0;
		if (nowActive == active)
		{
			return;
		}
		active = nowActive;

		int tick = client.getTickCount();
		if (active)
		{
			activeTick = tick;
			endTick = tick + durationTicks() - 1;

			NPC owned = tracker.getOwned();
			if (owned != null)
			{
				configManager.setRSProfileConfiguration(ThrallInOneConfig.GROUP, SAVED_END_KEY,
					(mapClock() + endTick - tick) + ":" + owned.getIndex());
			}
			log.debug("Thrall timer started at tick {} ({} ticks after the spawn): expect expiry at tick {}; saved for index {}",
				tick, tracker.getOwnedSpawnTick() < 0 ? "?" : tick - tracker.getOwnedSpawnTick(), endTick,
				owned == null ? "-" : owned.getIndex());
		}
		else
		{
			if (activeTick >= 0)
			{
				log.debug("Thrall lasted {} ticks after the varbit, predicted {}", tick - activeTick, endTick - activeTick);
			}
			activeTick = -1;
			endTick = -1;
			configManager.unsetRSProfileConfiguration(ThrallInOneConfig.GROUP, SAVED_END_KEY);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
				active = false;
				activeTick = -1;
				endTick = -1;
				break;
			default:
				break;
		}
	}

	/**
	 * Ticks left as whole seconds, rounded to the nearest, so a full cast at
	 * 99 Magic (99 ticks, 59.4 s) starts at 59 and the last tick shows 1.
	 */
	static int seconds(int ticks)
	{
		return (ticks * 6 + 5) / 10;
	}

	/** "59s": seconds only, as the timer shows them. */
	static String format(int ticks)
	{
		return seconds(ticks) + "s";
	}
}

package com.thrallinone;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Time left, drawn above our thrall in RuneScape Bold with a black outline. */
class ThrallTimerOverlay extends Overlay
{
	/** RuneScape Bold's own size: one font pixel per screen pixel. */
	static final int BASE_FONT_SIZE = 16;
	static final int MIN_FONT_SIZE = 8;
	static final int MAX_FONT_SIZE = 64;

	private final ThrallTracker tracker;
	private final ThrallTimer timer;
	private final ThrallInOneConfig config;

	// Derived once per size change, not every frame.
	private Font font;
	private int fontSize;

	@Inject
	ThrallTimerOverlay(ThrallTracker tracker, ThrallTimer timer, ThrallInOneConfig config)
	{
		this.tracker = tracker;
		this.timer = timer;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.timerEnabled())
		{
			return null;
		}
		NPC thrall = tracker.getOwned();
		int remaining = timer.getRemainingTicks();
		if (thrall == null || remaining < 0)
		{
			return null;
		}

		String text = ThrallTimer.format(remaining);
		int size = config.timerFontSize();
		// Set before placing the text, which centers it with the current font.
		graphics.setFont(font(size));
		Point location = thrall.getCanvasTextLocation(graphics, text, thrall.getLogicalHeight() + 40);
		if (location != null)
		{
			drawOutlined(graphics, text, location.getX(), location.getY(), outlineWidth(size), timerColor(config, remaining));
		}
		return null;
	}

	private Font font(int size)
	{
		if (font == null || fontSize != size)
		{
			Font base = FontManager.getRunescapeBoldFont();
			font = size == BASE_FONT_SIZE ? base : base.deriveFont((float) size);
			fontSize = size;
		}
		return font;
	}

	/** Black outline width in pixels: one font pixel, so it keeps up as the text grows. */
	static int outlineWidth(int fontSize)
	{
		return Math.max(1, Math.round(fontSize / (float) BASE_FONT_SIZE));
	}

	/**
	 * Text with a black outline all round, so it reads on any ground. A 1 px outline is the four
	 * straight neighbours; wider ones add the diagonals to fill the corners.
	 */
	private static void drawOutlined(Graphics2D graphics, String text, int x, int y, int width, Color color)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + width, y);
		graphics.drawString(text, x - width, y);
		graphics.drawString(text, x, y + width);
		graphics.drawString(text, x, y - width);
		if (width > 1)
		{
			graphics.drawString(text, x + width, y + width);
			graphics.drawString(text, x - width, y + width);
			graphics.drawString(text, x + width, y - width);
			graphics.drawString(text, x - width, y - width);
		}
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	private static Color timerColor(ThrallInOneConfig config, int remainingTicks)
	{
		// Compared in shown seconds, so every "5s" is the same color.
		return ThrallTimer.seconds(remainingTicks) <= config.timerWarnSeconds() ? config.timerWarnColor() : config.timerColor();
	}
}

package com.thrallinone;

import com.google.common.collect.ImmutableMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Keeps track of every thrall in the scene and works out which one belongs to
 * the local player.
 *
 * <p>The main signal is our own cast: the Resurrect cast graphic on our
 * player and the thrall's spawn arrive in the same tick, so the thrall is
 * claimed before it is first drawn, and the resurrection varbit (on about
 * five ticks later) confirms it. If that is missed, the varbit says we have a
 * thrall out but not which NPC it is, and every tick looks for ours (see
 * {@link ThrallClaim} for those rules). The claim is dropped the
 * moment the varbit clears, the NPC despawns, or the NPC is no longer in the
 * scene's NPC list. That last check runs every tick so a stale reference can
 * never keep an outline on screen after a teleport or a death (the
 * lingering-outline bug other thrall plugins have).
 *
 * <p>Losing the claimed thrall with the varbit still on is judged by
 * {@link ThrallLoss}: one left behind in another instance stops counting as
 * out after a short grace (the varbit can stay on long after it), and one
 * that ran out is not replaced by a teammate's. Any claim made without our
 * cast graphic on the spawn tick only takes the type our latest cast raised.
 */
@Slf4j
@Singleton
public class ThrallTracker
{
	/** A jump this far between ticks is a teleport; thralls do not follow teleports. */
	private static final int TELEPORT_DISTANCE = 20;
	/** Spawn ticks given to thralls found by a rescan, so they never count as a fresh cast. */
	private static final int UNKNOWN_SPAWN_TICK = Integer.MIN_VALUE / 2;
	/** The graphic our player shows when casting a Resurrect spell, and the thrall type it raises. */
	private static final Map<Integer, ThrallType> CAST_SPOTANIMS = ImmutableMap.of(
		SpotanimID.RESURRECT_GHOST_CAST_SPOTANIM, ThrallType.MAGIC,
		SpotanimID.RESURRECT_SKELETON_CAST_SPOTANIM, ThrallType.RANGED,
		SpotanimID.RESURRECT_ZOMBIE_CAST_SPOTANIM, ThrallType.MELEE);
	/** A thrall spawning this many ticks after our cast graphic can be ours (measured: same tick). */
	private static final int MY_CAST_TO_SPAWN_TICKS = 1;
	/** The resurrect cooldown is longer than this, so a cast graphic seen again sooner is the same cast. */
	static final int SAME_CAST_TICKS = 10;

	private final Client client;
	/** For the time left when our thrall is lost (the timer depends on this class, hence the provider). */
	private final Provider<ThrallTimer> timer;

	/** Every thrall in the scene, with when and where it appeared. */
	private final Map<NPC, Sighting> thralls = new IdentityHashMap<>();
	/** Thralls we have seen interact with another player: never ours. */
	private final Set<NPC> rejected = Collections.newSetFromMap(new IdentityHashMap<>());
	/** Thralls already logged as not claimed for being another type than our latest cast. */
	private final Set<NPC> wrongTypeLogged = Collections.newSetFromMap(new IdentityHashMap<>());
	/** Why our thrall went away with the varbit still on, and whether it's left behind. */
	private final ThrallLoss loss = new ThrallLoss();

	@Getter
	@Nullable
	private NPC owned;
	/** Why the current thrall was claimed, for the debug overlay. */
	@Getter
	private String claimReason = "";

	private boolean active;
	/** Tick the varbit last turned on, or -1; kept after a claim, unlike {@link #castTick}. */
	private int varbitOnTick = -1;
	/** Tick the scene last started loading, or -1. */
	private int loadTick = -1;
	private int castTick = -1;
	/** Tick our player last showed a Resurrect cast graphic, and the thrall type it raises. */
	private int myCastTick = -1;
	@Nullable
	private ThrallType myCastType;
	/**
	 * The last claim made from our cast graphic: the tick it was made, the
	 * cast it came from, and the thrall's spawn tick (relative to that cast)
	 * and distance from us.
	 */
	private int castClaimTick = -1;
	/** Spawn tick of our thrall when it was claimed from our cast, or -1. */
	private int ownedSpawnTick = -1;
	private int castClaimCastTick = -1;
	private int castClaimSpawnOffset;
	private int castClaimDistance;
	/** A claim made at spawn must be confirmed by the varbit by this tick, or it is dropped. */
	private int provisionalUntilTick = -1;
	/** NPC index of our thrall when we lost sight of it while the varbit was still on. */
	private int lostIndex = -1;
	/** We teleported away while our thrall was out; it stayed behind. */
	private boolean stranded;
	private boolean rescanPending;
	/** Read the resurrection varbit on the next tick (the plugin just started). */
	private boolean varbitUnread;
	@Nullable
	private WorldPoint lastPlayerLocation;
	@Nullable
	private WorldPoint locationBeforeLoad;

	@Inject
	ThrallTracker(Client client, Provider<ThrallTimer> timer)
	{
		this.client = client;
		this.timer = timer;
	}

	void start()
	{
		clear();
		// Started mid-game (or during a loading screen): read the varbit and
		// the scene on the first tick, since neither will send an event.
		varbitUnread = true;
		rescanPending = true;
	}

	void stop()
	{
		clear();
	}

	private void clear()
	{
		thralls.clear();
		rejected.clear();
		wrongTypeLogged.clear();
		release("reset");
		loss.reset();
		active = false;
		varbitOnTick = -1;
		loadTick = -1;
		castTick = -1;
		myCastTick = -1;
		myCastType = null;
		castClaimTick = -1;
		castClaimCastTick = -1;
		ownedSpawnTick = -1;
		lostIndex = -1;
		stranded = false;
		rescanPending = false;
		varbitUnread = false;
		lastPlayerLocation = null;
		locationBeforeLoad = null;
	}

	public Set<NPC> getThralls()
	{
		return Collections.unmodifiableSet(thralls.keySet());
	}

	public boolean isOwned(NPC npc)
	{
		return npc != null && npc == owned;
	}

	/**
	 * Our thrall is out as far as the game's varbit says, unless we left it
	 * behind in another instance (the varbit can stay on long after that).
	 */
	public boolean hasActiveThrall()
	{
		return active && !loss.isLeftBehind();
	}

	/** The resurrection varbit as the game has it, left behind or not. */
	public boolean isVarbitOn()
	{
		return active;
	}

	/** Our thrall stayed in a scene we left and none of ours came back: it doesn't count as out. */
	public boolean isLeftBehind()
	{
		return loss.isLeftBehind();
	}

	/** Tick our thrall began to count as left behind, or -1. */
	public int getLeftBehindTick()
	{
		return loss.getLeftBehindTick();
	}

	/** Why our thrall last went away with the varbit on, until we have one again. */
	public ThrallLoss.Kind getLossKind()
	{
		return loss.getKind();
	}

	/** Tick our thrall last went away with the varbit on, or -1 (as {@link #getLossKind}). */
	public int getLostTick()
	{
		return loss.getLostTick();
	}

	/** Spawn tick of our thrall if it was claimed from our cast (so its start is known), or -1. */
	public int getOwnedSpawnTick()
	{
		return owned == null ? -1 : ownedSpawnTick;
	}

	/** Tick our player last showed a Resurrect cast graphic, or -1. */
	public int getLastCastTick()
	{
		return myCastTick;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (ThrallType.isThrall(npc.getId()))
		{
			thralls.put(npc, sight(npc));
			logSpawn("spawned", npc);
			if (!tryClaimAtSpawn(npc))
			{
				tryClaim();
			}
		}
	}

	/**
	 * Our resurrection varbit turns on about five ticks after the thrall
	 * appears, which would leave it treated as somebody else's until then.
	 * Our own cast graphic comes first, though, so a thrall that appears
	 * beside us just after it is claimed on the spawn, before it is ever
	 * drawn. The varbit then confirms the claim, or it is dropped.
	 */
	private boolean tryClaimAtSpawn(NPC npc)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return false;
		}

		// In case the graphic's event was missed, look at our graphics now.
		noteCastGraphic(me);
		int sinceCast = client.getTickCount() - myCastTick;
		if (myCastTick >= 0 && sinceCast >= 0 && sinceCast <= MY_CAST_TO_SPAWN_TICKS)
		{
			if (claimFromCast(npc, me))
			{
				return true;
			}
			log.debug("Thrall {} spawned {} tick(s) after our cast but wasn't claimed: type {} (cast {}), {} tiles away{}",
				npc.getIndex(), sinceCast, ThrallType.of(npc.getId()), myCastType,
				distanceFromUs(me, npc.getWorldLocation()), npc == owned ? ", already ours" : "");
		}
		else if (myCastTick >= 0 && sinceCast > MY_CAST_TO_SPAWN_TICKS && sinceCast <= SAME_CAST_TICKS)
		{
			// Ours arriving late would show up here.
			log.debug("Thrall {} spawned {} ticks after our cast, too late to claim from it", npc.getIndex(), sinceCast);
		}
		return false;
	}

	/**
	 * Claim a thrall that appeared beside us right after our own cast graphic.
	 * A fresh cast replaces whatever we had, so this does not depend on the
	 * old thrall's varbit clear arriving first. A second matching thrall from
	 * the same cast's window (someone beside us cast the same spell a tick
	 * apart) takes over only if it fits our cast better.
	 */
	private boolean claimFromCast(NPC npc, Player me)
	{
		if (npc == owned)
		{
			return false;
		}
		int distance = distanceFromUs(me, npc.getWorldLocation());
		if (!ThrallClaim.fitsCastAtSpawn(myCastType, ThrallType.of(npc.getId()), distance))
		{
			return false;
		}

		int tick = client.getTickCount();
		Sighting sighting = thralls.get(npc);
		int spawnTick = sighting == null ? tick : sighting.tick;
		int spawnOffset = spawnTick - myCastTick;
		if (owned != null)
		{
			if (castClaimCastTick == myCastTick)
			{
				if (!ThrallClaim.replacesCastClaim(castClaimSpawnOffset, castClaimDistance, spawnOffset, distance))
				{
					return false;
				}
				rejected.add(owned);
				release("a better match for our cast appeared");
			}
			else
			{
				release("replaced by a new cast");
			}
		}
		claim(npc, "your cast");
		ownedSpawnTick = spawnTick;
		castClaimTick = tick;
		castClaimCastTick = myCastTick;
		castClaimSpawnOffset = spawnOffset;
		castClaimDistance = distance;
		// If the varbit is still on from the thrall being replaced, it won't
		// turn on again to confirm this one.
		provisionalUntilTick = active ? -1 : client.getTickCount() + ThrallClaim.CAST_WINDOW_BEFORE_TICKS + 2;
		return true;
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		Player me = client.getLocalPlayer();
		if (me == null || event.getActor() != me)
		{
			return;
		}

		if (noteCastGraphic(me))
		{
			// In game the graphic arrived just before the spawn in the same
			// tick; if the order is ever the other way round, the thrall is
			// already here.
			for (Map.Entry<NPC, Sighting> entry : new ArrayList<>(thralls.entrySet()))
			{
				if (entry.getValue().tick == myCastTick && !rejected.contains(entry.getKey()))
				{
					claimFromCast(entry.getKey(), me);
				}
			}
			return;
		}

		if (log.isDebugEnabled())
		{
			List<Integer> ids = new ArrayList<>();
			for (ActorSpotAnim spotAnim : me.getSpotAnims())
			{
				ids.add(spotAnim.getId());
			}
			log.debug("Our spotanims at tick {}: {}", client.getTickCount(), ids);
		}
	}

	/** Record a Resurrect cast graphic on us; true if it is a new cast. */
	private boolean noteCastGraphic(Player me)
	{
		for (Map.Entry<Integer, ThrallType> cast : CAST_SPOTANIMS.entrySet())
		{
			if (me.hasSpotAnim(cast.getKey()))
			{
				int tick = client.getTickCount();
				if (cast.getValue() == myCastType && myCastTick >= 0 && tick - myCastTick < SAME_CAST_TICKS)
				{
					// The same cast's graphic, seen again as another graphic changed
					// on us; moving the cast tick would widen the claim window.
					return false;
				}
				myCastTick = tick;
				myCastType = cast.getValue();
				log.debug("Our resurrect cast graphic {} at tick {}", cast.getKey(), myCastTick);
				return true;
			}
		}
		return false;
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Player me = client.getLocalPlayer();
		if (me != null && event.getActor() == me && me.getAnimation() != -1 && log.isDebugEnabled())
		{
			log.debug("Our animation {} at tick {}", me.getAnimation(), client.getTickCount());
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		if (ThrallType.isThrall(npc.getId()))
		{
			if (!thralls.containsKey(npc))
			{
				thralls.put(npc, sight(npc));
				logSpawn("changed into a thrall", npc);
			}
			tryClaim();
		}
		else
		{
			forget(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		forget(event.getNpc());
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.ARCEUUS_RESURRECTION_ACTIVE)
		{
			return;
		}

		boolean nowActive = event.getValue() != 0;
		log.debug("Resurrection varbit = {} at tick {}", event.getValue(), client.getTickCount());
		if (nowActive == active)
		{
			return;
		}
		active = nowActive;
		stranded = false;
		// Whatever we lost, the varbit now speaks for the thrall out (or none).
		loss.reset();

		if (active)
		{
			castTick = client.getTickCount();
			varbitOnTick = castTick;
			if (owned != null && provisionalUntilTick >= 0)
			{
				provisionalUntilTick = -1;
				claimReason += " (confirmed)";
				log.debug("Varbit confirmed thrall index={}", owned.getIndex());
			}
			tryClaim();
		}
		else
		{
			castTick = -1;
			if (owned != null && castClaimTick == client.getTickCount())
			{
				// The old thrall's varbit cleared in the same tick we claimed
				// its replacement; wait for it to turn on again for the new one.
				provisionalUntilTick = client.getTickCount() + ThrallClaim.CAST_WINDOW_BEFORE_TICKS + 2;
			}
			else
			{
				release("varbit cleared");
			}
			lostIndex = -1;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
				// NPC instances may not survive the reload; check them all on the next tick.
				locationBeforeLoad = lastPlayerLocation;
				rescanPending = true;
				loadTick = client.getTickCount();
				loss.sceneChanged(loadTick);
				break;
			case LOGIN_SCREEN:
			case HOPPING:
				clear();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}

		WorldPoint here = me.getWorldLocation();
		boolean teleported = isFarApart(lastPlayerLocation, here);
		lastPlayerLocation = here;

		if (varbitUnread)
		{
			varbitUnread = false;
			active = client.getVarbitValue(VarbitID.ARCEUUS_RESURRECTION_ACTIVE) != 0;
		}
		if (rescanPending)
		{
			rescanPending = false;
			teleported |= isFarApart(locationBeforeLoad, here);
			locationBeforeLoad = null;
			rescan();
		}

		if (teleported && active)
		{
			log.debug("Teleported with a thrall out: it stays behind");
			stranded = true;
		}

		// Despawn events are not guaranteed across every scene change, so
		// drop anything the scene no longer holds rather than outline a ghost.
		thralls.keySet().removeIf(npc -> !isInScene(npc));
		rejected.retainAll(thralls.keySet());
		wrongTypeLogged.retainAll(thralls.keySet());
		if (owned != null && !thralls.containsKey(owned))
		{
			lose("no longer in scene", teleported || isSceneChanging());
		}

		if (owned != null && provisionalUntilTick >= 0 && client.getTickCount() > provisionalUntilTick)
		{
			// Our varbit never turned on: it was somebody else's cast after all.
			rejected.add(owned);
			release("varbit never confirmed");
		}

		if (loss.tick(client.getTickCount()))
		{
			// lostIndex stays: should it turn up after all (slow to catch up), it's
			// claimed again ("same thrall again", type checked) and counts as out.
			log.debug("Thrall left behind at tick {}: lost at tick {} on a scene change and none of ours came back; "
				+ "not out from now, though the varbit is still on", client.getTickCount(), loss.getLostTick());
		}

		correctClaim(me);
		tryClaim();
	}

	/** The scene is loading or just loaded, or we teleported away from our thrall. */
	private boolean isSceneChanging()
	{
		return client.getGameState() == GameState.LOADING || stranded
			|| loadTick >= 0 && client.getTickCount() - loadTick <= 1;
	}

	/** Rebuild the thrall list from the scene and drop anything that is gone. */
	private void rescan()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		Map<NPC, Sighting> previous = new IdentityHashMap<>(thralls);
		thralls.clear();
		for (NPC npc : wv.npcs())
		{
			if (npc != null && ThrallType.isThrall(npc.getId()))
			{
				thralls.put(npc, previous.getOrDefault(npc, Sighting.UNKNOWN));
			}
		}
		rejected.retainAll(thralls.keySet());
		wrongTypeLogged.retainAll(thralls.keySet());
		if (owned != null && !thralls.containsKey(owned))
		{
			lose("gone after scene load", true);
		}
	}

	/**
	 * Fix a wrong claim as soon as the game tells us better: a thrall that
	 * interacts with another player is theirs, and one that interacts with us
	 * is ours.
	 */
	private void correctClaim(Player me)
	{
		if (owned == null)
		{
			return;
		}

		Actor target = owned.getInteracting();
		if (target instanceof Player && target != me)
		{
			log.debug("Thrall {} interacts with {}: not ours", owned.getIndex(), target.getName());
			rejected.add(owned);
			release("interacts with another player");
			return;
		}

		if (target != me)
		{
			ThrallType latestCast = latestCastType();
			for (NPC npc : thralls.keySet())
			{
				if (npc != owned && npc.getInteracting() == me && !rejected.contains(npc)
					&& ThrallClaim.fitsLatestCast(latestCast, ThrallType.of(npc.getId())))
				{
					claim(npc, "interacts with us (switched)");
					return;
				}
			}
		}
	}

	private void tryClaim()
	{
		// Our thrall ran out (the varbit clears a tick later): a teammate's
		// beside us isn't its replacement. Only our next cast claims again.
		if (!active || owned != null || thralls.isEmpty() || loss.isExpired())
		{
			return;
		}

		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}

		ThrallType latestCast = latestCastType();
		// The game keeps a thrall's NPC index for as long as it exists, so the
		// one we lost to a scene reload comes back under the same index, even
		// if it is far away by then.
		if (lostIndex >= 0)
		{
			for (NPC npc : thralls.keySet())
			{
				if (npc.getIndex() == lostIndex && !rejected.contains(npc)
					&& ThrallClaim.fitsLatestCast(latestCast, ThrallType.of(npc.getId())))
				{
					claim(npc, "same thrall again");
					return;
				}
			}
		}

		int tick = client.getTickCount();
		ThrallClaim.Mode mode;
		if (castTick >= 0 && tick - castTick <= ThrallClaim.CAST_WINDOW_AFTER_TICKS)
		{
			mode = ThrallClaim.Mode.FRESH_CAST;
		}
		else if (stranded || loss.isLeftBehind())
		{
			mode = ThrallClaim.Mode.INTERACTING_ONLY;
		}
		else
		{
			mode = ThrallClaim.Mode.REACQUIRE;
		}

		WorldPoint myLocation = me.getWorldLocation();
		List<ThrallClaim.Candidate<NPC>> candidates = new ArrayList<>();
		for (Map.Entry<NPC, Sighting> entry : thralls.entrySet())
		{
			NPC npc = entry.getKey();
			if (rejected.contains(npc) || npc.isDead())
			{
				continue;
			}
			Sighting sighting = entry.getValue();
			Actor target = npc.getInteracting();
			int spawnOffset = castTick >= 0 ? sighting.tick - castTick : UNKNOWN_SPAWN_TICK;
			int distance;
			boolean otherPlayerAsClose;
			if (mode == ThrallClaim.Mode.FRESH_CAST && sighting.distance >= 0)
			{
				// By the time the varbit turns on (five ticks after the spawn) a
				// thrall may have run off to attack something, so judge a fresh
				// cast by where it appeared, which is beside its caster.
				distance = sighting.distance;
				otherPlayerAsClose = sighting.otherPlayerAsClose;
			}
			else
			{
				WorldPoint npcLocation = npc.getWorldLocation();
				distance = npcLocation.distanceTo(myLocation);
				otherPlayerAsClose = isOtherPlayerAsClose(me, npc.getWorldView(), npcLocation, distance);
			}
			candidates.add(new ThrallClaim.Candidate<>(
				npc,
				distance,
				target == me,
				target instanceof Player && target != me,
				otherPlayerAsClose,
				spawnOffset,
				ThrallType.of(npc.getId())));
		}

		ThrallClaim.Candidate<NPC> pick = ThrallClaim.pick(candidates, mode, latestCast);
		if (pick != null)
		{
			claim(pick.getThrall(), pick.isInteractingWithMe() ? "interacts with us" : mode.name().toLowerCase().replace('_', ' '));
			return;
		}
		if (!log.isDebugEnabled())
		{
			return;
		}
		if (mode == ThrallClaim.Mode.FRESH_CAST)
		{
			log.debug("Tick {} (cast {}): no thrall claimed from {}", tick, castTick, candidates);
		}
		// Once per thrall: one we would have taken but for its type.
		ThrallClaim.Candidate<NPC> anyType = latestCast == null ? null : ThrallClaim.pick(candidates, mode, null);
		if (anyType != null && wrongTypeLogged.add(anyType.getThrall()))
		{
			log.debug("Not claiming thrall id={} index={} ({}, {} tiles): {}, our latest cast was {}",
				anyType.getThrall().getId(), anyType.getThrall().getIndex(), mode.name().toLowerCase().replace('_', ' '),
				anyType.getDistance(), anyType.getType(), latestCast);
		}
	}

	/** The type of thrall our latest cast raised, or null if unknown ({@link ThrallClaim#latestCastType}). */
	@Nullable
	private ThrallType latestCastType()
	{
		return ThrallClaim.latestCastType(myCastType, myCastTick, varbitOnTick);
	}

	/** When and where a thrall appeared, read the moment we first see it. */
	private Sighting sight(NPC npc)
	{
		int tick = client.getTickCount();
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return new Sighting(tick, -1, false);
		}
		WorldPoint npcLocation = npc.getWorldLocation();
		int distance = distanceFromUs(me, npcLocation);
		return new Sighting(tick, distance, isOtherPlayerAsClose(me, npc.getWorldView(), npcLocation, distance));
	}

	/**
	 * Tiles from us to a thrall that may have just been raised. We can cast
	 * while running, two tiles a tick, so the thrall may rise where we stood
	 * at the start of this tick rather than where we are now.
	 */
	private int distanceFromUs(Player me, WorldPoint location)
	{
		int distance = location.distanceTo(me.getWorldLocation());
		if (lastPlayerLocation != null)
		{
			distance = Math.min(distance, location.distanceTo(lastPlayerLocation));
		}
		return distance;
	}

	private boolean isOtherPlayerAsClose(Player me, @Nullable WorldView wv, WorldPoint npcLocation, int myDistance)
	{
		if (wv == null)
		{
			return false;
		}
		for (Player player : wv.players())
		{
			if (player != null && player != me && player.getWorldLocation().distanceTo(npcLocation) <= myDistance)
			{
				return true;
			}
		}
		return false;
	}

	private void claim(NPC npc, String reason)
	{
		owned = npc;
		claimReason = reason;
		ownedSpawnTick = -1;
		castTick = -1;
		stranded = false;
		provisionalUntilTick = -1;
		lostIndex = -1;
		if (loss.getKind() != ThrallLoss.Kind.NONE)
		{
			log.debug("Thrall lost at tick {} ({}) replaced after {} ticks{}", loss.getLostTick(),
				loss.getKind().name().toLowerCase().replace('_', ' '), client.getTickCount() - loss.getLostTick(),
				loss.isLeftBehind() ? ", after it counted as left behind" : "");
		}
		loss.reset();
		log.debug("Claimed thrall id={} index={} ({})", npc.getId(), npc.getIndex(), reason);
	}

	private void release(String reason)
	{
		if (owned != null)
		{
			log.debug("Released thrall id={} index={} ({})", owned.getId(), owned.getIndex(), reason);
		}
		owned = null;
		claimReason = "";
		ownedSpawnTick = -1;
		provisionalUntilTick = -1;
	}

	/**
	 * Our thrall's NPC went away while it may still be out. Judge why
	 * ({@link ThrallLoss}): unless it ran out, remember it so it can be picked
	 * up again.
	 */
	private void lose(String reason, boolean sceneChange)
	{
		if (owned != null && active)
		{
			// Before the release, while the timer still knows this thrall's start.
			int remaining = timer.get().getRemainingTicks();
			ThrallLoss.Kind kind = loss.lost(client.getTickCount(), sceneChange, remaining);
			lostIndex = kind == ThrallLoss.Kind.EXPIRY ? -1 : owned.getIndex();
			log.debug("Lost our thrall id={} index={} at tick {} with {} ticks left: {}", owned.getId(), owned.getIndex(),
				client.getTickCount(), remaining, kind.name().toLowerCase().replace('_', ' '));
		}
		release(reason);
	}

	private void forget(NPC npc)
	{
		if (thralls.remove(npc) == null)
		{
			return;
		}
		rejected.remove(npc);
		wrongTypeLogged.remove(npc);
		if (npc == owned)
		{
			lose("despawned", isSceneChanging());
		}
	}

	private void logSpawn(String what, NPC npc)
	{
		if (!log.isDebugEnabled())
		{
			return;
		}
		Player me = client.getLocalPlayer();
		Actor target = npc.getInteracting();
		Sighting sighting = thralls.get(npc);
		log.debug("Thrall {} id={} index={} tick={} castTick={} myCastTick={} varbit={} distance={} otherAsClose={} interacting={}",
			what, npc.getId(), npc.getIndex(), client.getTickCount(), castTick, myCastTick, active,
			sighting == null ? -1 : sighting.distance, sighting != null && sighting.otherPlayerAsClose,
			target == null ? "none" : target == me ? "you" : target.getName());
	}

	private static final class Sighting
	{
		/** For thralls found by a rescan: never a fresh cast, place unknown. */
		static final Sighting UNKNOWN = new Sighting(UNKNOWN_SPAWN_TICK, -1, false);

		final int tick;
		/** Tiles from us when it appeared, or -1 if unknown. */
		final int distance;
		/** Another player stood at least as close to it when it appeared. */
		final boolean otherPlayerAsClose;

		Sighting(int tick, int distance, boolean otherPlayerAsClose)
		{
			this.tick = tick;
			this.distance = distance;
			this.otherPlayerAsClose = otherPlayerAsClose;
		}
	}

	private static boolean isInScene(NPC npc)
	{
		WorldView wv = npc.getWorldView();
		return wv != null
			&& wv.npcs().byIndex(npc.getIndex()) == npc
			&& ThrallType.isThrall(npc.getId());
	}

	private static boolean isFarApart(@Nullable WorldPoint a, WorldPoint b)
	{
		return a != null && a.distanceTo2D(b) > TELEPORT_DISTANCE;
	}
}

package com.thrallinone;

import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The three thrall combat styles. Every thrall NPC (Arceuus base, the Leagues
 * imp cosmetics and the Deadman cosmetics) maps to exactly one of these, in
 * {@link ThrallNpcs}.
 */
@Getter
@RequiredArgsConstructor
public enum ThrallType
{
	// Players see a thrall's type as its combat style, everywhere.
	MAGIC("Mage"),
	RANGED("Ranged"),
	MELEE("Melee");

	private final String displayName;

	/** The type of a thrall NPC ({@link ThrallNpcs}), or null for any other NPC. */
	@Nullable
	public static ThrallType of(int npcId)
	{
		return ThrallNpcs.type(npcId);
	}

	public static boolean isThrall(int npcId)
	{
		return ThrallNpcs.isThrall(npcId);
	}
}

